  /* ===================================================================
     1. CONFIG — the knobs a new game changes first.
     =================================================================== */
  var CONFIG = {
    title:   "Radiam",
    /* One sentence, and the stage below plays it: the finger rocks the toothed
       outer ring one slot, the amber bead it carries joins the two ambers
       already sitting on the 12 o'clock ray, and the ray pays. */
    tagline: "<b class=\"w-turn\">Turn</b> one or more rings to line up <b class=\"w-three\">three</b> beads on one <b class=\"w-ray\">ray</b>",
    gameSeconds: 40,                 // round length in seconds; 0 = endless

    // Store links used by every CTA. The right one is picked at runtime from the
    // user agent. Until this game has a real listing all three point at the
    // newrare site, where the game can actually be played — never leave a
    // placeholder store URL here, it ships as a 404 on the device.
    storeUrl: {
      ios:     "https://newrare.app/#playables",
      android: "https://newrare.app/#playables",
      fallback:"https://newrare.app/#playables"
    },

    // Design resolution — all game logic and all DOM overlays use these units.
    designWidth: 720,
    designHeight: 1280,
    bg: "#070512",

    /* THE PAINTED HALL GOES BEHIND THE ROUND, not only behind the intro and
       the end screen. The five `radiam-background-phone-NN` scenes ARE the
       five worlds (ladder.biomes), so a round that kept painting a ground of
       its own over them would show one picture and never the other four. The
       motor lays it in as a CSS layer under the canvas (Art.dressFrame),
       Art.backdrop moves it with the world in reset(), and buildBg() asks
       Art.scene() before building a ground at all.

       What it replaces was decorative and nothing else: a radial sky and a
       wall of gears embedded as a 52 KB JPEG, which is exactly the picture the
       painted halls now carry — once per world instead of once for all five.
       The well and the rays stay, because those are contrast and the name of
       the game, not scenery. */
    sceneArt: true,

    // One round disc centred in Layout: it can never reach the score, the
    // timer or the install button, whatever the device does to the frame.
    layout: { hudHeight: 150, ctaHeight: 112, sideMargin: 26 },

    // The gesture IS the game: you put a finger on a ring and turn it. SPACE
    // therefore only starts and replays — a synthetic tap at a fixed point
    // would grab a ring the player never chose. Mouse-drag covers the desktop.
    intro: { logo: "logo", demo: "drag", caption: "" },
    keyboard: true,

    hud: { score: true, timer: true },

    /* ONE TRACK, SIX BEDS. The bed is three minutes long and a round plays a
       STRETCH of it rather than all of it — one per world, named next to that
       world's palette in `ladder.biomes[].music` and handed to Music.play by
       reset(), so the machine changes music when it changes hall instead of
       looping the same thirty seconds for thirty levels. The entry points are
       the track's own seams, measured and not guessed (see docs/MUSIC.md): the
       body enters at 24 s, the core at 71, the outro at 143, and the fade-out
       starts at 178.

       `menu` is the other end of it: the track's own opening, pitched down by
       its playback rate, under the menu, the map and the panels (the web
       target's screens — a playable has none of them). It is the one window
       that does NOT take the house's `gain: 0.5`, because this opening is a
       sparse arpeggio measured 25 dB under the body — halving it again would
       put the menus back to silence, which is the thing a menu bed is for.
       The section IS the attenuation here. See docs/ENGINE.md, `Music`. */
    music: {
      volume: 0.10, fade: 1.8,
      menu: { from: 0, length: 24, rate: 0.85, gain: 1 }
    },

    // All user-facing copy in one place.
    copy: {
      start:      "Tap to play",
      ctaBar:     "Install now",
      ctaEnd:     "Play the full game",
      replay:     "Replay the demo",
      scoreLabel: "Score",
      timeLabel:  "Time",
      endScore:   "Final score",
      gameOver:   "Jammed!",
      timeUp:     "Time's up!",
      eclipsed:   "Eclipsed!"
    },

    /* --- the dial ---------------------------------------------------------
       Three coaxial plates on one hub, each carrying `slots` beads in its own
       housings, and `slots` rays drawn between the hub and the toothed rim.
       Drag a plate and it turns alone; the two others hold. When the three
       beads sitting on one ray share a colour they pop, and the emptied
       housings are re-fed from outside the rim.

       Everything is expressed as a FRACTION of `unit` — the rim radius, which
       is derived from Layout — so the same numbers hold on a tall phone and
       inside a squat ad frame. `ballR` gives the bead radii; the orbits are
       NOT authored, they are stacked outward from the hub so that the same
       `gap` of empty sky shows between the hub and the first track and between
       every pair of tracks. Hand-written orbits drifted: the middle and outer
       housings ended up overlapping while the inner pair had a clear gap, and
       the three plates stopped reading as three. The touch bands that decide
       "which plate did the finger land on" are split from those same radii,
       and the outermost reaches well past the rim so a thumb sliding off the
       disc keeps turning the plate it grabbed.

       The two numbers that shape the round most: `comboWindow`, the seconds a
       chain survives without a pop (short enough that sweeping blindly loses
       it, long enough that a deliberate second ray keeps it), and `colours`,
       whose length sets how often a ray happens to line up at all. */
    dial: {
      slots: 12,                     // beads per plate, and rays on the dial
      maxRadius: 330,                // the rim never grows past this (design px)
      margin: 8,                     // breathing room inside Layout
      ballR:  [0.068, 0.098, 0.125], // bead radius, inner -> outer, x unit
      housing: 0.018,                // clearance a housing track adds around its bead
      gap:     0.045,                // the SAME sky between hub and every track
      grabPad: 1.40,                 // last touch band, well past the rim, x unit
      hubR:   0.175,                 // the cap the three plates turn on

      /* The dial is a DETENT wheel: let go and the plate clicks onto the
         nearest housing, it never coasts. Free spin was tried and thrown out —
         a released plate took ~0.6 s to stop, and since a ray only pays once
         the dial is at rest (see settled()), a player making a move every half
         second was never paid for any of them. */
      snap:   22,                    // how hard a released plate clicks onto its detent
      dwell:  0.08,                  // seconds a plate must hold still to pay

      fillDelay: 0.14,               // beat before the first refill leaves the rim
      fillStagger: 0.05,             // ...and between the three of one ray
      fillTime: 0.30,                // seconds from the rim to the outer housing
      fillFrom: 1.14,                // where a refill starts, x unit
      popTime: 0.26,                 // a popped bead's dissolve
      flareTime: 0.42,               // the ray staying lit after it paid

      /* THE FIVE HUES ARE SAMPLED OFF THE PAINTED BALLS, not chosen next to
         them. A bead is a bitmap now (see BALL_HUE), so these five are what
         everything AROUND it is drawn in — the armed ray's bar and halo, the
         flare a paid ray leaves, the vignette, the HUD punch, the sparks a pop
         throws — and a palette that disagreed with the paint would put a pink
         glow under a red marble on the one board where colour is the rules.
         Each one is the mean of its ball's saturated band (0.35..0.78 of the
         radius, so the white highlight and the dark rim are both out of it),
         lifted to 58% lightness at full saturation — the sampled body is a
         colour seen in shadow, and these are a light drawn on a dark dial.
         They are the same in every biome: a biome repaints the MACHINE, and a
         bitmap cannot be retinted. */
      colours:  ["#f63133", "#feb82a", "#29a0ff", "#8831f6", "#35f631"],
      /* What share of a ball cut's shorter side the ball itself takes up. A
         cut carries 20 px of transparent margin plus its own painted glow, so
         the file is wider than the marble in it; without this every bead would
         be drawn ~14% small and every housing would show a gap. Picked by eye
         on the dial, which is the only place it can be. */
      ballArtFill: 0.86,
      bagPer: 3,                     // beads of each hue in a plate's refill bag
      startColours: 4,               // hues in play at the start...
      colourUpAt: 22,                // ...the second the fifth joins a CLASSIC round
      colourUpLevel: 10,             // ...and the level it joins an eclipse one

      /* Supers. A move that pays two rays at once, or a chain reaching x4,
         upgrades one of the refills already flying in: two rays / x4 give a
         CHARGE, three rays / x8 give a NOVA. `fuseStep` is how fast a ring
         blast unzips its plate and `novaSpeed` how fast a nova's shockwave
         crosses the dial — both are what the wave you SEE is drawn from, so
         the picture and the beads going off can never disagree. */
      chargeNeed: 4,                 // rays that fill the hub's charge meter
      superCap:   3,                 // supers allowed on the dial at once
      fuseStep:   0.035,             // seconds between two housings of a blast
      novaSpeed:  1100,              // design px/s a nova's wave travels
      chargePing: 1.05,              // seconds a CHARGE's target ring takes to leave it
      novaSpin:   0.62,              // seconds the NOVA's spectrum takes to step one hue
      /* What a power PAYS. A bead taken by a wave is worth `blastScore` times
         the chain, and every further bead of the same wave adds `blastRamp`
         of that again, up to `blastRampMax`: emptying the dial with one nova
         is the biggest single payout in the game, and a two-bead splash still
         is not. The chain announces itself once, past `blastCall` beads. */
      blastScore: 30,                // a bead taken by a wave, times the combo
      blastRamp:  0.15,              // ...growing this much per bead of the chain
      blastRampMax: 3,               // ...up to this ceiling
      blastCall:  4,                 // beads before a chain reports its payout

      rayScore:   25,                // a ray pays this, times the combo
      comboMax:   8,
      comboWindow: 1.0,              // seconds a chain survives without a pop
      comboBonus: 20,                // extra per combo step, on every 4th
      /* One cascade can pay three rays in a third of a second, as three
         refills land one after another. Measured on the headless pilot: it
         stacked COMBO on COMBO five times in a 240 s run. The chain is ONE
         event, so the callout is rate-limited and the score counter carries
         what happens in between. */
      comboCall:  0.4,               // seconds between two COMBO callouts
      /* Several rays in one move multiply what that move already paid, by ray
         count — so the skill beat scales with the chain instead of handing out
         the same flat bonus at x1 and at x8. The fourth tier is the NOVA
         callout's: four rays at once is the rarest move on this dial. */
      multiMult: [1, 2.5, 5, 8],

      wire:  "#6f5ea8",              // the whole machine is drawn in this
      plate: "#3d2c85",              // the housing track under the beads
      hub:   "#120c2c",
      sky:   ["#241a52", "#0d0827", "#050310"],
      rays:  36,                     // the radiance painted behind the dial

      /* The finale. The clock never cuts a move short: it hands the round over
         to a wind-down that waits for the dial, then plays the machine out. */
      finaleWait:  4.5,              // seconds the board is given to go quiet
      finaleCalm:  0.55,             // stillness it must then HOLD (see quiet())
      finaleDrain: 0.85,             // the light draining into the hub...
      finaleDrama: 2.0,              // ...inside the whole power-down

      star2: 7000, star3: 18000,

      /* --- THE SPECIAL BEADS ------------------------------------------------
         Eight of them, and the dial shipped with two: a CHARGE that unzips the
         plate it sits on, and a NOVA that is wild and takes its colour off the
         board. The six below are what turns thirty levels into thirty
         different games (see `ladder`), and each one is a different SHAPE of
         answer to the same board:

           BOMB   clears the WHOLE dial, and the supers it reaches go off in
                  turn. The top of the ladder: CHARGE empties a ring, NOVA a
                  colour, BOMB everything.
           FIRE   pops the two rays either side of its own.
           LASER  fires straight through the hub and pops the ray opposite.
           SCORE  arms a round-wide multiplier for a few seconds — x2, x5 or
                  x10, the bigger face burning the shorter.
           SLOW   holds the eclipse's ink back. The one relief power, and the
                  only one that does nothing at all to the beads.
           ICE    the one HAZARD. It matches like any bead, but breaking it
                  freezes the plate it sat on: that ring cannot be turned until
                  `iceRays` more rays have paid.

         Everything here is per-bead and instant except the two that carry a
         clock, and both of those are capped by construction — see `iceMax`
         (the cold may never hold all three plates) and `mulTime`. */
      bombSpeed: 900,                // design px/s the bomb's wave crosses the dial
      fireDelay: 0.07,               // beat before a neighbouring ray catches
      laserDelay: 0.11,              // ...and before the beam reaches the far side
      iceRays: 2,                    // rays that must pay before a frozen plate turns
      iceTime: 8,                    // ...and the seconds that thaw it whatever happens
      iceMax: 2,                     // plates the cold may hold at once — never three
      mulSteps: [2, 5, 10],          // the score bead's three faces
      mulTime:  [6, 5, 4],           // ...and how long each one burns
      /* The window multiplies a RAY and the chain milestone, never the beads a
         wave takes — see scoreHit, and the bench that forced it. */
      slowTime: 6,                   // seconds a SLOW bead holds the ink back
      slowFactor: 0.34,              // ...and what it multiplies the eclipse rate by
      specTeach: 3                   // times a power names itself before it goes quiet
    },

    /* --- THE LADDER — what makes thirty levels thirty games ----------------
       A lerp says HARDER. It cannot say DIFFERENT, and thirty rounds of the
       same dial turning faster is one level played thirty times. This is the
       other half, and the shape of it comes straight from games/arcider (see
       docs/LEVELS.md, *the first game to use applyLevel*).

       Two tables, and between them they own everything a level is beyond its
       difficulty:

         biomes  FIVE whole looks, one per stretch of the climb. A biome is the
                 bead's own MATERIAL — one of the five picked by eye in
                 lab/bubble.html — and the palette the machine is painted with
                 under it. Swapping the bead alone would stand vinyl stickers
                 on a neon dial, which reads as a bug; the five hues move with
                 it, because the colour of a bead IS the gameplay and a
                 material that fights its own palette costs the player moves.

         levels  THIRTY ROWS, each naming the special beads in play. Almost
                 every row carries one or two of the eight, never the
                 catalogue: a level is the one where you meet the laser, or the
                 one where the ice meets the bomb. That is the variation, and
                 it is why a row is a list and not a difficulty. `ice` is the
                 share of refills that come in frozen — the only entry here
                 that is a hazard rather than a reward.

       Read by `applyLevel` (section 6). The playable never calls it and so
       never sees any of this: it keeps the hard enamel bead and the
       CHARGE / NOVA pair it shipped with, which is the creative as designed. */
    ladder: {
      /* A BIOME IS THE MACHINE, NOT THE BEAD. It was both for one build, each
         biome naming a bead material this file painted itself — sticker, soap,
         gem, ink, neon, ported out of lab/bubble.html. The painted balls took
         that half over: a bitmap cannot be retinted, so the five hues are
         fixed now (see dial.colours) and a biome repaints everything the beads
         sit ON. Five worlds of six levels, with the bead style changing twice
         inside each of them.

         `sky` is the three stops of the radial the hall is lit with, `wire`
         the machine's whole line work, `plate` the housing track under the
         beads, `hub` the cap the three plates turn on.

         `scene` is the painted hall the intro and the end screen wear
         (`assets/image/master/radiam-background-phone-NN.png` ->
         `CONFIG.art.backgroundPhoneNN`), moved by `Art.backdrop` in reset();
         `music` is the stretch of CONFIG.music's track this world rides, moved
         by `Music.play` on the very next line. The picture and the bed turn
         over on the same line of the table, so they can only ever turn over
         together. A playable ships the first of each and never leaves it. */
      biomes: [
        { name: "ATELIER",   scene: "backgroundPhone01",
          music: { from: 24,  length: 29.5 },
          sky: ["#241a52", "#0d0827", "#050310"],
          wire: "#6f5ea8", plate: "#3d2c85", hub: "#120c2c" },
        { name: "LAGOON",    scene: "backgroundPhone02",
          music: { from: 53.5, length: 28.5 },
          sky: ["#1b2450", "#070f26", "#03060f"],
          wire: "#5f7aa8", plate: "#27407a", hub: "#0a1226" },
        { name: "RELIQUARY", scene: "backgroundPhone03",
          music: { from: 82,  length: 30 },
          sky: ["#3a1450", "#160726", "#06020e"],
          wire: "#8b5ea8", plate: "#4d2170", hub: "#1a0a2c" },
        { name: "SUMI",      scene: "backgroundPhone04",
          music: { from: 112, length: 31 },
          sky: ["#2b2440", "#12101f", "#07060c"],
          wire: "#8d8299", plate: "#3a3450", hub: "#15121d" },
        { name: "CIRCUIT",   scene: "backgroundPhone05",
          music: { from: 143, length: 35 },
          sky: ["#141033", "#08061a", "#020108"],
          wire: "#4d6fc8", plate: "#1c2760", hub: "#070a1e" }
      ],
      // Which biome each stretch wears. Five entries, six levels apiece, and
      // it is read off the LEVEL NUMBER and not off `d`: the two roads out of
      // a fork have to be the same world.
      biomeFrom: [1, 7, 13, 19, 25],

      /* THE BEAD STYLE, ONE PER TWO LEVELS — fifteen of the twenty designs on
         the sheets, ordered to rise with the climb and to sit inside their
         biome: three styles to a world, so the board changes under the player
         twice as often as the room does.

         The five left on the sheet are not spares by accident. Every one of
         them carries a motif dead in the CENTRE of the ball — a star, a ringed
         planet, a four-point sparkle, a diamond, a bullseye — and the centre of
         a bead is exactly where a special's glyph is struck (see drawBadge). A
         painted bullseye under the CHARGE's concentric rings is not a style, it
         is a bead the player has to read twice. So the fifteen that ship are
         the ones whose paint is all-over or off-centre; the one that comes back
         is the star, for the endless run a perfect board unlocks, because that
         node on the map is drawn as a star and nothing else here is. */
      styles: [1, 17, 6, 2, 11, 12, 4, 20, 7, 5, 14, 16, 8, 15, 19],
      baseStyle:  1,     // a round with no level — the playable's only style
      bonusStyle: 3,     // ...and the endless run a perfect board unlocks

      /* THE THIRTY ROWS. `pool` is what the level may hand out, split by tier
         inside section 6 — a two-ray move or a x4 chain buys a small one, a
         three-ray move or a x8 chain buys a big one — so a level with no big
         special simply pays its big beats in small ones.

         Read it down the column and the shape is the teaching order: one new
         bead at a time, alone on the level it arrives on, then paired with
         what came before. The ice is never the newcomer AND the only thing on
         a level, because a level whose one new idea is a penalty is a level
         nobody wants to reach. */
      levels: [
        { pool: ["charge"],                    ice: 0    },  //  1  the meter, and nothing else
        { pool: ["charge"],                    ice: 0    },  //  2
        { pool: ["charge"],                    ice: 0    },  //  3
        { pool: ["charge", "nova"],            ice: 0    },  //  4  the wild bead arrives
        { pool: ["nova"],                      ice: 0    },  //  5  ...and holds the level alone
        { pool: ["charge", "nova"],            ice: 0    },  //  6
        { pool: ["bomb"],                      ice: 0    },  //  7  BOMB, alone
        { pool: ["charge", "bomb"],            ice: 0    },  //  8
        { pool: ["nova", "bomb"],              ice: 0    },  //  9
        { pool: ["score"],                     ice: 0    },  // 10  the multiplier, alone
        { pool: ["charge", "score"],           ice: 0    },  // 11
        { pool: ["bomb", "score"],             ice: 0    },  // 12
        { pool: ["fire"],                      ice: 0    },  // 13  FIRE, alone
        { pool: ["charge", "fire"],            ice: 0    },  // 14
        { pool: ["laser"],                     ice: 0    },  // 15  LASER, alone
        { pool: ["fire", "laser"],             ice: 0    },  // 16  the two ray powers meet
        { pool: ["nova", "laser"],             ice: 0    },  // 17
        { pool: ["fire", "score"],             ice: 0    },  // 18
        { pool: ["charge"],                    ice: 0.06 },  // 19  ICE, against the safest boon
        { pool: ["fire"],                      ice: 0.08 },  // 20
        { pool: ["laser", "score"],            ice: 0.08 },  // 21
        { pool: ["nova"],                      ice: 0.10 },  // 22
        { pool: ["charge", "bomb"],            ice: 0.10 },  // 23
        { pool: ["laser", "score"],            ice: 0.12 },  // 24
        { pool: ["slow"],                      ice: 0.10 },  // 25  SLOW, when the ink is fast
        { pool: ["charge", "slow"],            ice: 0.12 },  // 26
        { pool: ["fire", "laser"],             ice: 0.14 },  // 27
        { pool: ["bomb", "score"],             ice: 0.14 },  // 28
        { pool: ["nova", "slow"],              ice: 0.16 },  // 29
        { pool: ["bomb", "nova", "score"],     ice: 0.18 }   // 30  the only row with three
      ]
    }
  };

  /* ===================================================================
     2. ASSETS — embedded base64 data URIs only (no network requests ever).
     Generate entries with tools/lab/embed-asset.mjs. Draw the graphics on canvas:
     every embedded byte counts against the 5 MB budget.

     SOUND EFFECTS ALWAYS COME FROM assets/audio/sfx/ — that shared library is the
     palette for every game, so the whole catalogue sounds like one product.
     Pick a clip per event, trim it to the useful part and re-encode it small,
     then embed it under a short game-side key:

       ffmpeg -i assets/audio/sfx/<clip>.mp3 -t 0.4 -ac 1 -ar 32000 -b:a 64k gem.mp3
       node tools/lab/embed-asset.mjs gem.mp3 --key gem

     Keep a comment naming the source clip next to every key (below), and pitch
     a single sample with Sound.clip(name, vol, rate) instead of embedding
     variations. Sound.beep / Sound.arp stay available, but only as a fallback
     for an event with no clip.
     =================================================================== */
  var ASSETS = {
    images: {
      // assets/image/icon/thumb/radiam.png — the app icon shown on the intro, the
      // 320 px cut the gallery already loads (same bytes, no second export)
      "logo": "data:image/png;base64,",
    },
    sounds: {
      // assets/audio/sfx/*.{mp3,ogg}, trimmed and re-encoded mono 32 kHz / 64 kbps
      // pop: "data:audio/mpeg;base64,SUQzBAAAAAA…"
      // The background bed, looped and crossfaded by Music (see CONFIG.music).
      // The playable ships ONE window of the track — the first world's, all of
      // which it can reach without a level; the web target ships the whole of
      // it instead (`web.music` in the manifest):
      //   ffmpeg -ss 24 -t 29.5 -i assets/audio/music/radiam.mp3 \
      //          -ac 1 -ar 44100 -b:a 64k music.mp3
      "music": "data:audio/mpeg;base64,",
      // --- the dial's events, from assets/audio/sfx/ (trimmed, mono 32 kHz/64 kbps)
      // tick: click-metallic-01   (a plate crossing a detent)
      "tick": "data:audio/mpeg;base64,",
      // pop: pop-high-01   (a ray pays, pitched by the chain)
      "pop": "data:audio/mpeg;base64,",
      // land: mallet-plink-01   (a refill reaching its housing)
      "land": "data:audio/mpeg;base64,",
      // chain: harp-ascending-01   (a combo milestone)
      "chain": "data:audio/mpeg;base64,",
      // multi: harp-pad-success-01   (two rays in one move)
      "multi": "data:audio/mpeg;base64,",
      // charge: whoosh-whistle-ascending-02   (a super lands on the dial)
      "charge": "data:audio/mpeg;base64,",
      // blast: hit-sport-03   (a CHARGE unzips its ring)
      "blast": "data:audio/mpeg;base64,",
      // nova: harp-roll-01   (a NOVA takes a whole colour)
      "nova": "data:audio/mpeg;base64,",
      // End-screen cues, shared by every game (played through Sound.cue, so a
      // game that drops them falls back to the synthesized beeps).
      // uiScore: chime-ping-correct-01
      // uiStar:  mallet-chime-ring-02  (pitched per star)
      // uiRow:   beep-select-01
      uiScore: "data:audio/mpeg;base64,",
      uiStar: "data:audio/mpeg;base64,",
      uiRow: "data:audio/mpeg;base64,"
    }
  };

  /* ===================================================================
     6. GAME — RADIAM: three plates on one hub, and the rays between them.

     The board is three coaxial rings, each holding `slots` beads in its own
     housings, over `slots` rays fixed in screen space. A ring turns alone
     under the finger; the two others hold. Once the dial comes to rest the
     board is re-read: any ray whose three beads share a colour pops and its
     housings are re-fed from outside the toothed rim — which is what makes
     cascades, and why a chain can outlive the move that started it.

     The whole thing is one integer per housing. A ring stores its beads in its
     OWN frame (`slots[k]`, k never moves) plus `step`, the number of detents it
     has been turned; the bead a screen ray `s` is looking at is therefore
     `slots[(s - step) mod N]`. Nothing is ever shuffled, and reading the board
     costs one modulo per ring.
     =================================================================== */
  var Game = (function () {
    var D = CONFIG.dial;
    var N = D.slots, TAU = Math.PI * 2, SLOT = TAU / N;

    /* A housing still holds ONE INTEGER, and that has not changed with eight
       specials in the game — it is what makes reading the whole board one
       modulo per ring, and what lets a refill in flight carry its own power
       through the same field every other bead uses.

         bits 0..7    the hue, an index into D.colours
         bits 8..15   the special, one bit each — a bead is never two things
         bits 16..17  the SCORE bead's face: 0 -> x2, 1 -> x5, 2 -> x10

       Every special goes off when the ray it sits on pays, and every one of
       them pops the supers its own wave reaches, so a dial with two charges on
       one plate empties in a single chain. `null` still means "housing empty,
       refill on its way".

       ICE is in the same field and is deliberately NOT in BOON: it is the one
       bead the player does not want, so it must never eat a reward slot (see
       liveSupers) and must never be handed out by grant(). */
    var CHARGE = 0x0100, NOVA  = 0x0200, BOMB  = 0x0400, SCORE = 0x0800,
        FIRE   = 0x1000, LASER = 0x2000, ICE   = 0x4000, SLOW  = 0x8000;
    var SUPER = 0xff00;                 // any special at all, hazard included
    var BOON  = SUPER & ~ICE;           // ...and the seven a player wants
    var MULSHIFT = 16;                  // where the score bead keeps its face
    function hueOf(v) { return v & 0xff; }
    function mulOf(v) { return (v >> MULSHIFT) & 3; }

    /* The catalogue, and the ONLY place a special's name, bit and tier are
       written down. A level's `pool` (CONFIG.ladder.levels) is a list of these
       keys, and grant() picks out of it by tier: a two-ray move or a x4 chain
       buys a SMALL one, a three-ray move or a x8 chain buys a BIG one. A pool
       with no big special pays its big beats in small ones rather than
       reaching outside the level for something the player has not met. */
    var SPEC = {
      charge: { bit: CHARGE, tier: 1, word: "Charge" },
      fire:   { bit: FIRE,   tier: 1, word: "Fire"   },
      laser:  { bit: LASER,  tier: 1, word: "Laser"  },
      score:  { bit: SCORE,  tier: 1, word: "Score"  },
      slow:   { bit: SLOW,   tier: 1, word: "Slow"   },
      nova:   { bit: NOVA,   tier: 2, word: "Nova"   },
      bomb:   { bit: BOMB,   tier: 2, word: "Bomb"   },
      ice:    { bit: ICE,    tier: 0, word: "Frozen" }
    };

    // Geometry — every one of these is rebuilt from Layout by layout().
    var cx = 0, cy = 0, unit = 0, rimR = 0, hubR = 0;
    var sprites = [], novaBodies = [], novaShells = [], wheel = null, bg = null;
    // The three plates exist from the first frame, because the motor fits the
    // canvas (and calls onResize) before the first reset().
    /* `cold` is the rays a frozen plate still owes before it turns again and
       `coldT` the seconds that thaw it whatever happens — a board where no ray
       can pay must never leave a plate locked forever (see iceHit). */
    var rings = [
      { idx: 0, slots: new Array(N), angle: 0, step: 0, bag: [], prev: 0, still: 9, cold: 0, coldT: 0 },
      { idx: 1, slots: new Array(N), angle: 0, step: 0, bag: [], prev: 0, still: 9, cold: 0, coldT: 0 },
      { idx: 2, slots: new Array(N), angle: 0, step: 0, bag: [], prev: 0, still: 9, cold: 0, coldT: 0 }
    ];

    // Run state.
    var score, matches, multis, supers, cleared, combo, bestCombo, comboLeft, palette;
    var comboCallAt;               // last COMBO callout, to coalesce a cascade
    var charge;                     // rays banked toward the next free CHARGE
    var blastRun, blastGain, bestBlast;   // the power chain currently burning
    var best, clock, grab, touched, flyers, blobs, flares, resting, armed;
    var finale;                     // the wind-down after the clock (see onTimeUp)
    var fuses, sweeps, novas, booms, beams;
    var mulK, mulLeft, mulSpan;     // the SCORE bead's round-wide multiplier

    /* --- what the level makes of the game --------------------------------
       Set by applyLevel and read everywhere. With no level — the playable, and
       the endless run at 90/90 — they stay exactly what the file shipped: the
       hard enamel bead, the studio palette, and the CHARGE / NOVA pair. */
    var LAD = CONFIG.ladder;
    var BIO = null;                 // the biome in force, or null for the playable
    var POOL = ["charge", "nova"];  // the specials this level may hand out
    var ICE_RATE = 0;               // ...and the share of refills that come in frozen
    var MUL_FACE = 1;               // how many faces of the SCORE bead are in play

    /* The machine as the file wrote it, snapshotted at load: a biome writes
       over D.colours and the four machine colours IN PLACE (so the armed glow,
       the flares, the vignettes and the pops all follow it without a line of
       their own), and a round with no level has to get them back. */
    var SKIN0 = { sky: D.sky.slice(), wire: D.wire, plate: D.plate, hub: D.hub };

    // --- small shared maths ------------------------------------------------
    // Angles are measured from 12 o'clock, clockwise, because that is how the
    // dial is read: ray s is at s * SLOT, full stop.
    function mod(a, n) { var m = a % n; return m < 0 ? m + n : m; }
    function wrap(a) { while (a > Math.PI) a -= TAU; while (a < -Math.PI) a += TAU; return a; }
    function px(a, rad) { return cx + Math.sin(a) * rad; }
    function py(a, rad) { return cy - Math.cos(a) * rad; }
    function shade(hex, k) {
      var n = parseInt(hex.slice(1), 16);
      return "rgb(" + Math.round((n >> 16 & 255) * k) + "," +
                      Math.round((n >> 8 & 255) * k) + "," +
                      Math.round((n & 255) * k) + ")";
    }

    /* --- geometry ---------------------------------------------------------
       The dial is a single disc centred in Layout, so it is clear of the HUD,
       the CTA bar and the device insets by construction. Every radius is a
       fraction of `unit`, the rim: change the frame and the whole machine
       scales with it.

       The three housing tracks are STACKED, not placed: each one is as wide as
       its bead plus `housing`, and the walk outward leaves exactly `gap` of
       sky before the next. That is what makes the three plates read as three —
       the eye reads the dark rings between them, so they have to be equal, and
       the only way to guarantee that under three different bead sizes is to
       derive the orbits instead of writing them down. */
    function layout() {
      cx = Layout.cx; cy = Layout.cy;
      unit = Math.min(Math.min(Layout.w, Layout.h) * 0.5 - D.margin, D.maxRadius);
      rimR = unit; hubR = unit * D.hubR;
      var gap = unit * D.gap, edge = hubR + gap, prev = hubR;
      for (var i = 0; i < 3; i++) {
        var r = rings[i];
        r.ballR = unit * D.ballR[i];
        r.band = r.ballR * 2 + unit * D.housing;  // width of its housing track
        r.rad = edge + r.band / 2;                // ...so its inner wall is `edge`
        // A touch is claimed by the plate whose track it is nearest: the border
        // between two plates sits in the middle of the sky between them.
        r.inner = (prev + edge) / 2;
        prev = r.rad + r.band / 2;
        edge = prev + gap;
        if (i > 0) rings[i - 1].outer = r.inner;
      }
      rings[2].outer = unit * D.grabPad;
      // ...except the innermost, which swallows most of the hub: a thumb aiming
      // at the small inner plate lands short as often as not, and there is
      // nothing else down there to grab.
      rings[0].inner = hubR * 0.62;
      buildSprites();
      buildBg();
      Eclipse.build();                 // ...and the contaminated copy of it
    }

    /* One bead sprite per colour and per plate size, drawn once. Per-frame the
       board is 36 drawImage calls and no gradients — the motor's rule about
       never lighting a glow inside the frame loop.

       HARD ENAMEL (picked in lab/bubble.html): every edge here is a hard one.
       The bead that shipped first stacked three soft ones — a 34%-of-radius
       alpha halo, a radial gradient fading to a dark rim, and a translucent
       rim arc — and the dial read as fogged. This one is four flat discs: an
       enamel wall, the body colour, a shade crescent and a gloss cap, the last
       two cut to the body by a clip. The sprite is also barely wider than the
       bead now, since there is no halo to make room for. */
    /* --- THE BEAD IS A PAINTED BALL ---------------------------------------
       Twenty designs, each painted in the five game colours plus a rainbow,
       out of six sheets in `assets/image/master/radiam-object-ball-*.png`. They
       are cut by `tools/lab/cut-objects.mjs --grid 5x4`, and the grid is the
       whole reason that command has a grid mode: the six sheets are the same
       twenty designs recoloured, so design 7 has to be design 7 in all six.
       Cutting by blob AREA — which is what the tool did before, and the right
       answer for a wall of gears — cannot promise that, because a halo a few
       pixels wider in one recolour reorders everything after it in silence.

       A STYLE IS SIX FILES: `radiam-ball-<colour>-NN.webp` reaches
       `CONFIG.art.ballRedNN` like every other picture, with no manifest key and
       no ASSETS edit, and `ArtImages` is where the canvas reads it.

       This replaced five bead MATERIALS this file used to paint itself —
       sticker, soap, gem, ink and neon, ported out of lab/bubble.html. They
       were good and they are gone, because painted art beats a canvas
       pastiche of it and because keeping both would be two systems doing one
       job. What survives is `paintEnamel`, and only as the fallback: a build
       whose artwork is missing still gets a legible dial rather than a hole,
       which is the same rule the rest of the artwork answers to.

       The sprite is still BAKED once per colour and per plate size, so the
       frame loop is the same 36 drawImage calls it always was — the painted
       ball costs a decode at load and nothing per frame. */

    /* Which file a hue index asks for. The order is CONFIG.dial.colours', and
       it is the order the six sheets were painted in. */
    var BALL_HUE = ["red", "yellow", "blue", "purple", "green"];

    /* The style in force. It is not null for a round with no level: the
       playable ships style 1 and nothing else (tools/build/build.mjs holds the
       other fourteen back from a creative that has no levels to show them on),
       so the ad is painted too. */
    var STYLE = CONFIG.ladder.baseStyle, ART_ON = false;

    /* `ArtImages.ballRed07`, if the build carries it and it decoded. Everything
       here has to survive the picture being absent — a game degrades to the
       enamel bead on its own, it never ships a placeholder. */
    function ballArt(name, style) {
      if (!style) return null;
      var k = "ball" + name.charAt(0).toUpperCase() + name.slice(1) +
              (style < 10 ? "0" : "") + style;
      var img = typeof ArtImages !== "undefined" ? ArtImages[k] : null;
      return img && img.width ? img : null;
    }

    /* HARD ENAMEL — the bead this file used to draw, and now the floor under
       the painted one. Four flat discs: an enamel wall, the body colour, a
       shade crescent and a gloss cap, the last two cut to the body by a clip.
       No halo, no gradient, nothing soft — the bead before it stacked three
       soft edges and the dial read as fogged. */
    function disc(g, x, y, r) { g.beginPath(); g.arc(x, y, r, 0, TAU); g.fill(); }
    function paintEnamel(g, m, r, hex) {
      g.fillStyle = shade(hex, 0.38);                 // the enamel wall
      disc(g, m, m, r);
      g.fillStyle = hex;                              // the flat body
      disc(g, m, m, r * 0.87);
      g.save();
      g.beginPath(); g.arc(m, m, r * 0.87, 0, TAU); g.clip();
      g.fillStyle = shade(hex, 0.70);                 // the side turned away
      disc(g, m + r * 0.42, m + r * 0.50, r * 0.95);
      g.fillStyle = rgba("#ffffff", 0.50);            // the gloss cap
      disc(g, m - r * 0.06, m - r * 0.66, r * 0.62);
      g.restore();
      g.fillStyle = "#ffffff";                        // the spark
      disc(g, m - r * 0.30, m - r * 0.36, r * 0.13);
    }

    /* One sprite per colour and per plate size, baked once.

       `ballArtFill` is the one number this needs and it cannot be derived: a
       cut carries `--pad 20` of transparent margin AND the ball's own painted
       glow inside it, so the file is wider than the ball it holds. Scaling the
       image to `2r` would draw every bead about 14% small and open a gap in
       every housing. The fill says what share of the shorter side the BALL
       occupies, the image keeps its own aspect so the glow is never squashed,
       and the sprite is padded enough to hold the overflow. */
    function ballSprite(hex, r, ci) {
      var pad = Math.max(3, r * 0.24), s = Math.ceil((r + pad) * 2);
      var c = document.createElement("canvas"); c.width = s; c.height = s;
      var g = c.getContext("2d");
      var art = ballArt(BALL_HUE[ci % BALL_HUE.length], STYLE), k, dw, dh;
      if (art) {
        k = (r * 2) / (Math.min(art.width, art.height) * D.ballArtFill);
        dw = art.width * k; dh = art.height * k;
        g.drawImage(art, s / 2 - dw / 2, s / 2 - dh / 2, dw, dh);
      } else {
        paintEnamel(g, s / 2, r, hex);
      }
      return c;
    }

    /* --- the NOVA bead ----------------------------------------------------
       A nova belongs to no colour — it is the wild bead — so instead of a flat
       body it wears every colour at once, as a spectrum turning slowly inside
       a white enamel wall. It shipped as a plain white bead with the palette
       stuck round it as spokes, and it read as "a white bead with a decoration"
       rather than as the one bead that is all of them.

       The spectrum is PRE-RENDERED, because the motor forbids lighting a
       gradient inside the frame loop — but the TURN is not baked. The bead is
       two layers instead of a filmstrip: a body that the frame loop spins under
       `ctx.rotate`, and the lighting blitted flat on top of it.

       It shipped as a 20-frame strip covering one hue step, and that strip
       cannot loop. Rolling the spectrum on by one hue leaves the same wheel
       turned a fifth of a revolution — not the wheel it started on — so
       replaying frame 0 snapped the colours back 72 degrees every `novaSpin`
       seconds. A live rotation has no seam to hide, turns at whatever the frame
       rate is, and costs two sprites per plate size instead of twenty. */
    /* The sweep walks the palette in HUE order, not in the order the game
       hands the colours out — and it interpolates in HSL along the SHORT arc,
       not in RGB. Two things the first build got wrong and the bead paid for:
       the palette's green sitting next to its pink blended through mud, and an
       RGB lerp between any two hues ~70 degrees apart passes through their grey
       average, so the whole wheel came out pastel against the enamel beads
       around it. Sorted and turned in HSL, only the hue moves and every wedge
       stays as saturated as the palette it is made of. Built once. */
    function toHsl(hex) {
      var n = parseInt(hex.slice(1), 16);
      var r = (n >> 16 & 255) / 255, g = (n >> 8 & 255) / 255, b = (n & 255) / 255;
      var mx = Math.max(r, g, b), mn = Math.min(r, g, b), d = mx - mn;
      var l = (mx + mn) / 2, h = 0, s = 0;
      if (d > 0) {
        s = d / (1 - Math.abs(2 * l - 1));
        if (mx === r) h = mod((g - b) / d, 6);
        else if (mx === g) h = (b - r) / d + 2;
        else h = (r - g) / d + 4;
        h /= 6;
      }
      return [h, s, l];
    }
    function hueWheel() {
      var i, w = [];
      for (i = 0; i < D.colours.length; i++) w.push(toHsl(D.colours[i]));
      w.sort(function (a, b) { return a[0] - b[0]; });
      return w;
    }
    // one step of the sweep: the short way round the wheel between two stops
    function mix(a, b, t) {
      var dh = b[0] - a[0];
      if (dh > 0.5) dh -= 1; else if (dh < -0.5) dh += 1;
      return "hsl(" + (mod(a[0] + dh * t, 1) * 360).toFixed(1) + "," +
             ((a[1] + (b[1] - a[1]) * t) * 100).toFixed(1) + "%," +
             ((a[2] + (b[2] - a[2]) * t) * 100).toFixed(1) + "%)";
    }

    // Both layers share one footprint, so a single sprite size serves both.
    function novaCanvas(r) {
      var pad = Math.max(2, r * 0.06), s = Math.ceil((r + pad) * 2);
      var c = document.createElement("canvas"); c.width = s; c.height = s;
      return c;
    }

    /* Layer one, the part that turns: the white enamel wall with the spectrum
       laid inside it. The wheel is SEG wedges whose colour walks the palette
       and blends between neighbours, so the eye reads a continuous sweep rather
       than five slices of a pie. The wall is a plain circle and the disc is
       centred, so spinning this layer moves the colours and nothing else. */
    function novaBody(r) {
      var c = novaCanvas(r), s = c.width;
      var g = c.getContext("2d"), m = s / 2, i, u, f, j, a0, a1;
      var cols = wheel, n = cols.length, SEG = 60, body = r * 0.90;
      g.fillStyle = "#e8edff";                        // the white enamel wall
      g.beginPath(); g.arc(m, m, r, 0, TAU); g.fill();
      g.save();
      g.beginPath(); g.arc(m, m, body, 0, TAU); g.clip();
      for (i = 0; i < SEG; i++) {
        u = i / SEG;
        f = u * n;                                    // where that sits in the palette
        j = Math.floor(f);
        g.fillStyle = mix(cols[j % n], cols[(j + 1) % n], f - j);
        a0 = u * TAU - TAU / SEG * 0.6;               // wedges overlap: no seams
        a1 = u * TAU + TAU / SEG * 0.6;
        g.beginPath(); g.moveTo(m, m);
        g.arc(m, m, body, a0, a1); g.closePath(); g.fill();
      }
      g.restore();
      return c;
    }

    /* Layer two, the part that must NOT turn: the same enamel treatment as a
       plain bead — the side turned away, the gloss cap, the spark. Riding it on
       the spin would send the highlight round the bead and break the one thing
       that ties the nova to the family it belongs to: every bead on the dial
       is lit from the same corner. */
    function novaShell(r) {
      var c = novaCanvas(r), s = c.width;
      var g = c.getContext("2d"), m = s / 2, body = r * 0.90;
      g.save();
      g.beginPath(); g.arc(m, m, body, 0, TAU); g.clip();
      g.fillStyle = "rgba(10,6,26,.17)";              // the side turned away
      g.beginPath(); g.arc(m + r * 0.42, m + r * 0.50, r * 0.95, 0, TAU); g.fill();
      g.fillStyle = rgba("#ffffff", 0.26);            // the gloss cap — light, or it washes the spectrum out
      g.beginPath(); g.arc(m - r * 0.06, m - r * 0.66, r * 0.62, 0, TAU); g.fill();
      g.restore();
      g.fillStyle = "#ffffff";                        // the spark
      g.beginPath(); g.arc(m - r * 0.30, m - r * 0.36, r * 0.13, 0, TAU); g.fill();
      return c;
    }

    function buildSprites() {
      var c, i;
      /* Is this build painted? One probe, on the one file every style has:
         either the artwork is there and the whole dial is painted, or none of
         it is and the whole dial is enamel. There is no half-painted board —
         a dial mixing a photographed marble with a drawn disc would read as a
         bug rather than as a fallback. */
      ART_ON = !!ballArt(BALL_HUE[0], STYLE);
      sprites = [];
      for (c = 0; c < D.colours.length; c++) {
        sprites.push([ballSprite(D.colours[c], rings[0].ballR, c),
                      ballSprite(D.colours[c], rings[1].ballR, c),
                      ballSprite(D.colours[c], rings[2].ballR, c)]);
      }
      novaBodies = []; novaShells = [];
      if (ART_ON) {
        /* THE WILD BEAD IS PAINTED TOO, and it is the rainbow cut of the very
           style the round is wearing — so the one bead that belongs to no
           colour still belongs to the same set as the five that do. It does
           NOT spin: the drawn spectrum had to turn because a static wheel of
           five wedges reads as a pie chart, but a painted marble carries its
           own highlight, and rolling that highlight round the bead would break
           the one thing every bead on this dial shares — they are all lit from
           the same corner. */
        for (i = 0; i < 3; i++) novaBodies.push(novaSprite(rings[i].ballR));
        return;
      }
      // ...and without the artwork, the drawn spectrum it shipped with: a body
      // the frame loop spins and a lighting layer blitted flat on top of it.
      wheel = hueWheel();
      for (i = 0; i < 3; i++) {
        novaBodies.push(novaBody(rings[i].ballR));
        novaShells.push(novaShell(rings[i].ballR));
      }
    }

    // The painted wild bead: the same sprite as any other, from the rainbow cut.
    function novaSprite(r) {
      var pad = Math.max(3, r * 0.24), s = Math.ceil((r + pad) * 2);
      var c = document.createElement("canvas"); c.width = s; c.height = s;
      var g = c.getContext("2d"), art = ballArt("rainbow", STYLE), k, dw, dh;
      if (!art) return c;
      k = (r * 2) / (Math.min(art.width, art.height) * D.ballArtFill);
      dw = art.width * k; dh = art.height * k;
      g.drawImage(art, s / 2 - dw / 2, s / 2 - dh / 2, dw, dh);
      return c;
    }

    // How far the spectrum has turned, in radians. `novaSpin` is the time one
    // hue takes to walk into the next, so a whole revolution is one per colour
    // in the wheel. Read off the clock, so every nova on the dial is in
    // lockstep and the speed is the same at any frame rate.
    function novaAngle() {
      return mod(clock / (D.novaSpin * D.colours.length), 1) * TAU;
    }

    /* The radiance the dial sits in, painted ONCE into an offscreen canvas:
       the frame loop only ever blits it.

       THE HALL ITSELF IS THE PAINTED SCENE (CONFIG.sceneArt), a CSS layer
       under the canvas the frame pipeline has already wiped — so this canvas
       is TRANSPARENT where the world used to have a ground, and the world's
       own picture shows through. The sky gradient below it is the fallback for
       a build with no artwork on disk, and nothing else: it keeps a bare frame
       impossible.

       What is painted either way is the WELL — a radial that darkens hardest
       exactly where the disc lands. The board is 36 saturated beads on a cold
       machine, and a painted hall is busier than the gradient it replaced, so
       the one thing that cannot go is the shadow the beads are read against.
       The flat veil over the whole frame is the motor's `--scene-scrim`
       (packages/shell/motor.css), which is the same stop by another name. */
    function buildBg() {
      bg = document.createElement("canvas");
      bg.width = view.w; bg.height = view.h;
      var g = bg.getContext("2d"), i, well;
      if (!Art.scene()) {
        var sky = g.createRadialGradient(cx, cy, unit * 0.15, cx, cy, view.h * 0.78);
        sky.addColorStop(0, D.sky[0]); sky.addColorStop(0.55, D.sky[1]); sky.addColorStop(1, D.sky[2]);
        g.fillStyle = sky; g.fillRect(0, 0, view.w, view.h);
      }
      well = g.createRadialGradient(cx, cy, unit * 0.12, cx, cy, unit * 1.7);
      well.addColorStop(0, "rgba(5,3,16,.74)");
      well.addColorStop(0.58, "rgba(5,3,16,.46)");
      well.addColorStop(1, "rgba(5,3,16,0)");
      g.fillStyle = well; g.fillRect(0, 0, view.w, view.h);
      // long thin rays leaving the rim — the name of the game, and the reason
      // the disc reads as a source rather than a plate
      g.save(); g.translate(cx, cy);
      for (i = 0; i < D.rays; i++) {
        g.rotate(TAU / D.rays);
        var grd = g.createLinearGradient(0, -rimR, 0, -rimR * 2.7);
        grd.addColorStop(0, rgba(D.wire, i % 3 === 0 ? 0.26 : 0.13));
        grd.addColorStop(1, rgba(D.wire, 0));
        g.fillStyle = grd;
        g.beginPath();
        g.moveTo(-2.5, -rimR); g.lineTo(2.5, -rimR);
        g.lineTo(10, -rimR * 2.7); g.lineTo(-10, -rimR * 2.7);
        g.closePath(); g.fill();
      }
      g.restore();
      for (i = 0; i < 70; i++) {                    // dust, so the sky is not flat
        var a = Rand.range(0, TAU), d = Rand.range(rimR * 1.05, view.h * 0.75);
        g.fillStyle = rgba("#ffffff", Rand.range(0.04, 0.16));
        g.beginPath(); g.arc(px(a, d), py(a, d), Rand.range(1, 2.4), 0, TAU); g.fill();
      }
    }

    // --- the board ---------------------------------------------------------
    /* Beads are dealt from a per-plate BAG, not drawn uniformly at random.
       Uniform refills look fair and are not: a ray only pays when the same
       colour shows on all three plates, so every pop drains that colour from
       all three at once. Left alone the board walks into an equilibrium where
       each plate is dominated by a different colour and almost nothing can
       ever line up again — measured, a plate ending a round 10 beads out of 12
       in one colour. A bag holding `bagPer` of every colour, reshuffled when
       it runs dry, keeps each plate evenly mixed, which is both what the dial
       should look like and what keeps rays findable to the last second. */
    function drawColour(r) {
      var i, j, c, t;
      if (!r.bag.length) {
        for (c = 0; c < palette.length; c++)
          for (i = 0; i < D.bagPer; i++) r.bag.push(palette[c]);
        for (i = r.bag.length - 1; i > 0; i--) {
          j = Rand.int(0, i); t = r.bag[i]; r.bag[i] = r.bag[j]; r.bag[j] = t;
        }
      }
      return r.bag.pop();
    }
    function slotAt(r, s) { return r.slots[mod(s - r.step, N)]; }

    /* A fresh dial, then every ray that happened to line up on its own is
       broken by re-rolling the inner bead: the first pop has to be the
       player's move, not the shuffle's. */
    function seed() {
      var i, k, s, g;
      for (i = 0; i < 3; i++) {
        rings[i].angle = 0; rings[i].step = 0; rings[i].bag.length = 0;
        for (k = 0; k < N; k++) rings[i].slots[k] = drawColour(rings[i]);
      }
      for (s = 0; s < N; s++) {
        g = 0;
        while (g++ < 24 && slotAt(rings[0], s) === slotAt(rings[1], s)
                        && slotAt(rings[1], s) === slotAt(rings[2], s)) {
          rings[0].slots[mod(s - rings[0].step, N)] = drawColour(rings[0]);
        }
      }
    }

    /* A plate has crossed onto a new detent: click. It does NOT pay — see
       settled() for why. */
    function syncStep(r) {
      var st = Math.round(r.angle / SLOT);
      if (st === r.step) return;
      r.step = st;
      Sound.clip("tick", 0.16, 1.06 - r.idx * 0.09);
    }

    /* A ray only pays once the dial has COME TO REST: every plate parked on a
       detent and not moving for `dwell` seconds. Note it does NOT ask for the
       finger to be off — hold a plate still on the alignment you found and it
       pays under your thumb; that is the same gesture, without the wait.

       Paying on every detent the finger crosses was the obvious reading of the
       rule and it ruined the game: a careless sweep crossed ten detents a
       second and paid on all of them (measured, 190 rays a round against ~50
       for a player choosing moves), so choosing a move was worth nothing and
       the callouts never stopped. Resting makes the MOVE the unit of play, and
       `armed` — the rays that would pay right now, lit under the beads while
       you turn — is what tells the player mid-drag that they have found one. */
    function tickRest(r, dt) {
      var d = Math.abs(r.angle - r.prev);
      r.prev = r.angle;
      var off = Math.abs(r.angle - Math.round(r.angle / SLOT) * SLOT);
      if (off < SLOT * 0.18 && d < 0.6 * dt) r.still += dt; else r.still = 0;
    }
    function settled() {
      return rings[0].still >= D.dwell && rings[1].still >= D.dwell && rings[2].still >= D.dwell;
    }

    /* --- ECLIPSE — the shadow that fills the dial --------------------------
       The endless mode. There is no clock: what runs out is the BOARD. A
       shadow closes in over the machinery from the bottom of the frame toward
       12 o'clock, and the rays it swallows cannot pay — so the arc the player
       is allowed to play in narrows, and the same three plates have to feed a
       smaller and smaller window.

       It is INK, and it stains the machine rather than the room. The layer
       order is the whole design (see render): background, then the plates and
       the teeth, then the ink OVER them and clipped to them, then the beads.
       So the frame never goes dark, the ink is only ever seen on the
       machinery, and a bead sitting on inked plate is the signal — the beads
       themselves stay at full colour on top, because they are what the player
       reads to plan a move. Chosen from the ten candidates in
       lab/eclipse-fog.html, which draws them all the way the game draws this.

       What the shadow answers to, and nothing else:
         - a single ray            it STOPS for `HOLD` seconds
         - two rays or more        it gives ground back  (`multi`)
         - a whole plate emptied   it gives more back    (`blast`)

       The level is Tetris's: every `LINES` rays popped is one level, and the
       shadow closes `STEP` times faster at each. Nothing else accelerates it —
       the pressure comes from the player's own progress, which is what makes a
       good run end as decisively as a bad one.

       It ends the moment no ray is left. Note the last-stand that leaves open
       on purpose: at one lit ray you can no longer double, but you can pop
       that ray over and over, bank the hub's meter, and spend the CHARGE it
       buys to unzip a plate — a ring cleared is three rays of daylight back.

       It owns exactly ONE hook into the rules: `dead()`, read by rayColour.
       Since scan() feeds both the armed preview and the payout, the shadow can
       never light a ray it would then refuse to pay.

       WHICH MODE A ROUND RUNS IN is read at the top of Game.reset, from
       CONFIG.mode — so the two live side by side in one build and a round can
       switch between them. The web menu writes it (PLAY is the eclipse, the
       CLASSIC entry is the timed dial; see packages/webshell/menu.js and
       `web.modes` in the manifest); with nobody writing it, which is every
       playable build, the URL flag below decides and the dial is timed. The
       clock is the other half of the switch: this mode zeroes
       CONFIG.gameSeconds and takes the timer pill for its own two readouts,
       and `arm` puts both back for a CLASSIC round.

       URL flags — desk only, and the tuning ones need the mode flag:
         ?mode=eclipse            the endless mode, without the menu
         &ecl=<rate>,<step>       rays/s at level 1, and the per-level factor
         &push=<dbl>,<tpl>,<ring> ground given back, in rays
         &lines=<n>               rays popped per level
         &cover=<rays>            start with that much of the dial already dark
       ------------------------------------------------------------------- */
    var Eclipse = (function () {
      /* Tuned on the headless replay (a pilot that turns plates at random, so
         a deliberate player does better than these numbers). Playing has to be
         worth about twice doing nothing: under that the mode is a timer with
         extra steps, over it the shadow stops being a threat. */
      var GROW = 0.35;               // rays of dial eaten per second at level 1
      var STEP = 1.14;               // ...multiplied by this at every level
      var LINES = 10;                // rays popped per level, like Tetris
      var HOLD = 2;                  // seconds a single ray freezes the shadow
      var PUSH = { multi: 0.8, triple: 2, ring: 3 };   // ground back, in rays
      var WARN = 3;                  // lit rays left before the board screams

      // Reading location can THROW in a sandboxed ad iframe — same guard the
      // motor puts around its own ?perf= flag.
      var flag = false, start = 0;
      try {
        var q = location.search + location.hash;
        flag = /[?&#]mode=eclipse\b/.test(q);
        var m = /[?&#]ecl=([0-9.]+),([0-9.]+)/.exec(q);
        if (flag && m) { GROW = +m[1]; STEP = +m[2]; }
        var g = /[?&#]push=([0-9.]+),([0-9.]+),([0-9.]+)/.exec(q);
        if (flag && g) { PUSH.multi = +g[1]; PUSH.triple = +g[2]; PUSH.ring = +g[3]; }
        var l = /[?&#]lines=([0-9]+)/.exec(q);
        if (flag && l) LINES = Math.max(1, +l[1]);
        var c = /[?&#]cover=([0-9.]+)/.exec(q);
        if (flag && c) start = Math.min(N - 0.01, +c[1]);
      } catch (e) {}

      /* The timed dial's own two numbers, kept as authored: a player who comes
         back to CLASSIC after an eclipse run has to get its clock back, and
         this module is the only thing that ever touches them. */
      var SECONDS = CONFIG.gameSeconds, TIMER = CONFIG.hud.timer;
      var on = false;

      var cover = 0, free = N, freed = false, over = false;
      var lines = 0, level = 1, hold = 0, slowLeft = 0;
      var flash = 0, shove = 0, shown = -1;
      var shade0 = [], hits = [0, 0, 0], missed = [], misses = [];
      var ink = null, inkR = 0;

      /* Called at the very top of Game.reset — BEFORE layout() bakes the ink
         and before the motor's Round.reset reads the clock, which is the whole
         reason it is not simply part of reset() below. With no clock the mode
         frees both HUD pills for what it is actually played on: the level, and
         how many rays are still lit. */
      function arm() {
        on = api.on = CONFIG.mode ? CONFIG.mode === "eclipse" : flag;
        CONFIG.gameSeconds = on ? 0 : SECONDS;
        CONFIG.hud.timer = on ? false : TIMER;
      }

      function reset() {
        cover = start; free = N; freed = false; over = false;
        lines = 0; level = 1; hold = 0; slowLeft = 0;
        flash = 0; shove = 0; shown = -1;
        hits[0] = hits[1] = hits[2] = 0;
        misses.length = 0;
        for (var s = 0; s < N; s++) { shade0[s] = false; missed[s] = -9; }
        if (on) { recount(); HUD.setLeft(level, "Level"); HUD.setRight(lines, "Rays"); }
      }

      /* A SLOW bead does not stop the ink the way a single ray does — it puts
         it in treacle. Two different reliefs on one axis: a ray you found buys
         a full stop for two seconds, a bead you were given buys six seconds at
         a third of the speed, and the rim says which is running. */
      function rate() {
        return GROW * Math.pow(STEP, level - 1) * (slowLeft > 0 ? D.slowFactor : 1);
      }
      function slow(sec) {
        if (!on || over) return;
        slowLeft = Math.max(slowLeft, sec);
        flash = 0.7;
        Fx.flash("#3ff0a0", 0.14, 1.5);
      }

      /* The ink, baked ONCE per layout into a square the size of the dial.
         It is a texture, not a copy of anything: near black, with a few slow
         sheens across it so a big blot reads as ink and not as a hole punched
         in the game. Baking it is what makes the effect affordable — the blot
         changes shape every frame, the ink does not, so a frame costs one
         clipped drawImage the size of the dial instead of a screenful of
         gradients. It is also why the ink can never leak onto the background:
         the bitmap is only as big as the machine it stains. */
      function build() {
        if (!on) return;
        var i, g, x, y, r, grd, s;
        inkR = rimR * 1.01;                // the teeth end at rimR, nothing past it
        s = Math.ceil(inkR * 2);
        ink = document.createElement("canvas");
        ink.width = s; ink.height = s;
        g = ink.getContext("2d");
        g.fillStyle = "rgba(4,3,10,0.94)";
        g.fillRect(0, 0, s, s);
        for (i = 0; i < 9; i++) {
          x = Rand.range(0, s); y = Rand.range(0, s);
          r = Rand.range(s * 0.12, s * 0.42);
          g.save();
          g.translate(x, y); g.scale(1, Rand.range(0.2, 0.5)); g.rotate(Rand.range(-0.5, 0.5));
          grd = g.createRadialGradient(0, 0, 0, 0, 0, r);
          grd.addColorStop(0, "rgba(120,110,190,0.09)");
          grd.addColorStop(1, "rgba(120,110,190,0)");
          g.fillStyle = grd;
          g.beginPath(); g.arc(0, 0, r, 0, TAU); g.fill();
          g.restore();
        }
      }

      /* The blot's edge: two slow, wide frequencies down the radius, so it
         soaks rather than sweeps. It nearly stops while the shadow is held —
         ink holding still is the clearest tell that a single ray just bought
         the player two seconds.

         The amplitude is deliberately under half a slot: the edge can eat into
         a live ray's sector, but it can never reach the ray's CENTRE, which is
         where its three beads sit. So a bead on black is always a dead ray and
         a bead on plate is always a live one, whatever the edge is doing. */
      function wobble(r, sign) {
        var t = clock * (hold > 0 ? 0.18 : 1);
        return (Math.sin(r * 0.0072 + t * 0.6 + sign * 1.7) * 0.7 +
                Math.sin(r * 0.019 - t * 0.35) * 0.3) * SLOT * 0.3;
      }

      /* One wedge, apex at the hub, wobbling edges, closed well past the
         corners of the frame. `fresh` is false for the second subpath of the
         even-odd clip that carves the soft outer band. */
      function wedgePath(half, grow, fresh) {
        var i, r, a, n = 14, m, R0 = hubR * 0.25, R1 = inkR * 1.03;
        if (fresh) ctx.beginPath();
        ctx.moveTo(cx, cy);
        for (i = 0; i <= n; i++) {
          r = R0 + (R1 - R0) * (i / n);
          a = Math.PI - half - grow - wobble(r, -1);
          ctx.lineTo(px(a, r), py(a, r));
        }
        m = Math.max(3, Math.ceil((half + grow) * 4));      // follow the rim
        for (i = 1; i < m; i++) {
          a = Math.PI - half - grow + 2 * (half + grow) * (i / m);
          ctx.lineTo(px(a, R1), py(a, R1));
        }
        for (i = n; i >= 0; i--) {
          r = R0 + (R1 - R0) * (i / n);
          a = Math.PI + half + grow + wobble(r, 1);
          ctx.lineTo(px(a, r), py(a, r));
        }
        ctx.closePath();
      }

      /* How far the shadow reaches, as a half-angle off the bottom. A ray dies
         when its whole slot is inside it, which is what makes `cover` read in
         rays: 1 is the bottom ray alone, 11 leaves only 12 o'clock, 12 is the
         end of the round. */
      function reach() { return Math.min(Math.PI, cover * SLOT / 2); }
      function depth(s) { return Math.min(Math.PI, Math.abs(wrap(s * SLOT - Math.PI)) + SLOT / 2); }

      function recount() {
        var half = reach(), s, now, f = 0;
        freed = false;
        for (s = 0; s < N; s++) {
          now = depth(s) <= half + 1e-6;
          if (shade0[s] && !now) freed = true;
          shade0[s] = now;
          if (!now) f++;
        }
        free = f;
        /* The right pill counts the rays FUSED since the round began — that is
           line()'s job. What is LEFT is still watched here, because crossing
           the warning threshold is this mode's one alarm, and it must fire
           once per crossing rather than once per frame. */
        if (f !== shown) {
          shown = f;
          if (f <= WARN && f > 0) {
            Overlay.vignette(D.colours[0], 0.85, 520);
            Sound.clip("charge", 0.4, 0.7);
          }
        }
      }

      function update(dt) {
        var i;
        if (finale) return;                    // the machine is powering down
        if (slowLeft > 0) slowLeft = Math.max(0, slowLeft - dt);
        if (hold > 0) hold = Math.max(0, hold - dt);
        else cover = Math.min(N, cover + rate() * dt);
        if (flash > 0) flash = Math.max(0, flash - dt * 1.8);
        if (shove > 0) shove = Math.max(0, shove - dt * 2.4);
        for (i = misses.length - 1; i >= 0; i--) {
          misses[i].life -= dt;
          if (misses[i].life <= 0) misses.splice(i, 1);
        }
        recount();
        if (free <= 0 && !over) { over = true; eclipsed(); }
      }

      /* Ground given back. `word` is optional, and usually absent: a multi
         ray already announces itself in the clear band under the HUD, and two
         pops in that band on the same beat is one too many to read. The ink
         recoiling is the tell — it is drawn on the dial the player is looking
         at, which no callout can beat. Only the ring clear, which the player
         SPENT a super on and could otherwise mistake for the blast's own
         payout, says its name. */
      function give(rays, word) {
        if (!on || over) return;
        cover = Math.max(0, cover - rays);
        flash = 0.7; shove = 1;
        recount();
        if (word) Pop.show("bonus", { word: word, sub: "+" + rays + Lang.t(" rays"), at: "hudUnder" });
        Sound.clip("charge", 0.55, 1.15);
        Fx.flash("#8b6cff", 0.16, 1.6);
      }

      /* A ray paid. One is a breather — the shadow stops where it is, which is
         what keeps a player who can only find singles alive while they look
         for a double. Two or more give ground back, and hold as well: a double
         must never be worth less than a single on any axis. */
      function single() { if (on && !over) { hold = Math.max(hold, HOLD); flash = 0.5; } }
      function multi(n) {
        if (!on) return;
        hold = Math.max(hold, HOLD);
        give(n > 2 ? PUSH.triple : PUSH.multi);     // silent: pop() named it
      }

      // Tetris's clock: the lines are the rays, and only they move the level.
      function line() {
        if (!on) return;
        lines++;
        HUD.setRight(lines, "Rays");          // the round's running total
        if (lines % LINES) return;
        level++;
        HUD.setLeft(level, "Level");
        Pop.show("alert", { word: Lang.t("Level ") + level, at: "hudUnder" });
        Sound.clip("chain", 0.5, 1.18);
        Fx.flash("#ff4d6d", 0.14, 1.8);
        flash = 1;
      }

      // One bead taken by a wave, counted per plate...
      function bead(idx) { if (on) hits[idx]++; }
      // ...and read once the whole chain has burnt out. A plate is "cleared"
      // at N-1 of its N housings: one refill in flight is the normal state of
      // this board, and it must not cost the player the reward.
      function blast() {
        if (!on) return;
        var i, best = 0;
        for (i = 0; i < 3; i++) { if (hits[i] > best) best = hits[i]; hits[i] = 0; }
        if (best >= N - 1) give(PUSH.ring, "Ring cleared");
      }

      /* A move that WOULD have paid, landing on a ray the shadow owns. Without
         this the board simply says nothing and the player reads it as the game
         missing their alignment — so it is called out: the ray flares dead,
         the beads spit grey, and the machine gives a flat dud instead of the
         pop. Once per ray per second, because a cascade of refills re-reads
         the same board several times over. */
      function miss(s) {
        if (!on || over || clock - missed[s] < 1) return;
        missed[s] = clock;
        var r = rings[1], a = r.angle + mod(s - r.step, N) * SLOT;
        var x = px(a, r.rad), y = py(a, r.rad);
        misses.push({ s: s, life: 0.5 });
        Fx.burst(x, y, { color: ["#6f5ea8", "#2a2050"], count: 7, speed: 150,
                         life: 0.4, grav: 140, size: 4 });
        Pop.text(x, y, "Blocked", { color: "#8b6cff", size: 22, life: 0.6, tier: 1 });
        Sound.clip("tick", 0.4, 0.52);
      }

      /* The one hook. A single array lookup when the mode is off, because
         reset() never filled the array. */
      function dead(s) { return shade0[s] === true; }

      /* How deeply a POINT sits in the ink, 0..1 — the beads are drawn over
         the blot and are sunk by it (see drawBall). It is measured against the
         edge actually drawn, wobble included, so a bead darkens exactly as it
         is dragged across the rim instead of snapping when its ray dies; and
         it ramps over half a slot, so the bead is fully sunk about where its
         own ray is fully swallowed. Everything drawn as a bead gets it for
         free: the ones in their housings, the refills flying in, and the
         dissolving ones. */
      function sink(x, y) {
        if (!on || cover <= 0) return 0;
        var dx = x - cx, dy = y - cy;
        var r = Math.sqrt(dx * dx + dy * dy);
        var w = wrap(Math.atan2(dx, -dy) - Math.PI);
        var edge = reach() + wobble(r, w < 0 ? -1 : 1);
        return clamp((edge - Math.abs(w)) / (SLOT * 0.5), 0, 1);
      }

      /* A ray has just come OUT of the shadow, which only happens when the
         player pushed it back. The dial has not moved, so this is the only
         re-read of the board that will ever happen — without it the ground won
         earns nothing until the next move. Consumed on read. */
      function uncovered() {
        if (!freed) return false;
        freed = false;
        return true;
      }

      /* layer 0 — BEHIND everything, over the gears: one flat wedge and its
                   two fronts. Flat and source-over on purpose: this covers a
                   large part of the frame every single frame, and a gradient
                   or a multiply over that area is exactly the kind of fill a
                   phone's rasterizer runs out of budget on.
         layer 1 — over the beads, additive: the alignments the shadow is
                   sitting on, and the BLOCKED flare of a move that just died
                   in the dark. */
      function draw(layer) {
        var half = reach(), s, col, g, w, m, e, a0, a1;
        if (layer === 0) {
          if (half <= 0) return;
          if (!ink) {                        // the bake failed: still play fair
            ctx.fillStyle = rgba(D.sky[2], 0.82);
            wedgePath(half, 0, true); ctx.fill();
            return;
          }
          /* Everything below is clipped to the machine. That single circle is
             what makes the ink "only on the gears": it cannot reach the
             background, and the beads are drawn after it. */
          ctx.save();
          ctx.beginPath(); ctx.arc(cx, cy, inkR, 0, TAU); ctx.clip();
          /* The band OUTSIDE the blot first, at part alpha: ink does not end
             on a line, it thins into the paper. Two subpaths and an even-odd
             clip carve the band, so the body is painted once and the soft edge
             costs only its own width. */
          var band = SLOT * 0.2;
          if (half + band < Math.PI) {
            ctx.save();
            wedgePath(half, band, true);
            wedgePath(half, 0, false);
            ctx.clip("evenodd");
            ctx.globalAlpha = 0.42;
            ctx.drawImage(ink, cx - inkR, cy - inkR, inkR * 2, inkR * 2);
            ctx.globalAlpha = 1;
            ctx.restore();
          }
          ctx.save();
          wedgePath(half, 0, true);
          ctx.clip();
          ctx.drawImage(ink, cx - inkR, cy - inkR, inkR * 2, inkR * 2);
          ctx.restore();
          /* The wet rim of the blot. Held it goes to the game's own accent,
             won back it goes white — the two states the player has to read at
             a glance, on the one edge they are already watching. */
          /* The wet rim is the one edge the player is already watching, so it
             is where all three states are read: white for ground just won
             back, cyan for the ink held still by a ray, green for the ink
             merely slowed by a SLOW bead. */
          col = shove > 0 ? "#ffffff"
              : hold > 0 ? "#35e0ff"
              : slowLeft > 0 ? "#3ff0a0" : "#c9c2ff";
          wedgePath(half, 0, true);
          ctx.lineWidth = 14;
          ctx.strokeStyle = rgba(col, 0.05 + flash * 0.1);
          ctx.stroke();
          ctx.lineWidth = 1.6 + shove * 2;
          ctx.strokeStyle = rgba(col, 0.55 + flash * 0.35);
          ctx.stroke();
          ctx.restore();
          return;
        }
        // The alignments the shadow is holding: what pushing it back is worth,
        // dim enough never to compete with a ray that can actually pay.
        w = unit * 0.05;
        for (s = 0; s < N; s++) {
          if (!shade0[s]) continue;
          col = rawColour(s);
          if (col < 0) continue;
          ctx.save();
          ctx.translate(cx, cy); ctx.rotate(s * SLOT);
          g = ctx.createLinearGradient(0, -hubR, 0, -rimR);
          g.addColorStop(0, rgba(D.colours[col], 0));
          g.addColorStop(0.5, rgba(D.colours[col], 0.13 + 0.05 * Math.sin(clock * 7)));
          g.addColorStop(1, rgba(D.colours[col], 0));
          ctx.fillStyle = g;
          ctx.fillRect(-w / 2, -rimR, w, rimR - hubR);
          ctx.restore();
        }
        // ...and the ray that just died under it, flaring out.
        for (m = 0; m < misses.length; m++) {
          e = misses[m].life / 0.5;
          ctx.save();
          ctx.translate(cx, cy); ctx.rotate(misses[m].s * SLOT);
          g = ctx.createLinearGradient(0, -hubR, 0, -rimR);
          g.addColorStop(0, rgba("#8b6cff", 0));
          g.addColorStop(0.5, rgba("#8b6cff", 0.75 * e * e));
          g.addColorStop(1, rgba("#8b6cff", 0));
          ctx.fillStyle = g;
          ctx.fillRect(-unit * 0.055 * (2 - e), -rimR, unit * 0.11 * (2 - e), rimR - hubR);
          ctx.restore();
        }
      }

      /* The board is out. It goes through the motor's own wind-down, so the
         move under way still finishes and still pays — the round is over, but
         it is not cut off mid-gesture. */
      function eclipsed() {
        Pop.show("danger", { word: CONFIG.copy.eclipsed, at: "hudUnder" });
        Fx.shake(20, 0.5);
        onTimeUp();
      }

      /* `on` is a property rather than an accessor because every call site
         reads `Eclipse.on` fresh, and `arm` rewrites it once per round. */
      var api = { on: false, arm: arm, build: build, reset: reset, update: update,
               dead: dead, sink: sink, miss: miss, slow: slow,
               uncovered: uncovered, single: single, multi: multi, line: line,
               bead: bead, blast: blast, draw: draw,
               level: function () { return level; },
               lines: function () { return lines; },
               survived: function () { return Math.round(clock); } };
      return api;
    })();

    /* The colour a ray would pay in, or -1 if it would not. A NOVA is wild:
       it agrees with whatever the other two beads are, which is what makes it
       worth hunting rather than just worth having. */
    function rayColour(s) {
      if (Eclipse.dead(s)) return -1;      // the eclipse, and nothing else
      return rawColour(s);
    }
    function rawColour(s) {
      var c = -1, i, v;
      for (i = 0; i < 3; i++) {
        v = slotAt(rings[i], s);
        if (v === null) return -1;                  // a housing still being fed
        if (v & NOVA) continue;
        if (c < 0) c = hueOf(v); else if (c !== hueOf(v)) return -1;
      }
      // three novas on one ray: they pay in the first one's own hue
      return c < 0 ? hueOf(slotAt(rings[0], s)) : c;
    }

    /* The rays that would pay right now. */
    function scan() {
      var hits = [], s;
      for (s = 0; s < N; s++) if (rayColour(s) >= 0) hits.push(s);
      return hits;
    }

    function resolve(cascade) {
      var hits = scan(), s;
      if (hits.length) pop(hits, cascade);
      // ...and whatever the shadow just swallowed, so the board never simply
      // says nothing when the player had it right.
      if (Eclipse.on)
        for (s = 0; s < N; s++) if (Eclipse.dead(s) && rawColour(s) >= 0) Eclipse.miss(s);
    }

    /* Empty ONE housing: the bead dissolves, a refill is ordered from outside
       the rim, and whatever the bead was carrying is handed back so the caller
       can set off its super. Popping an already-empty housing is a no-op, which
       is what lets two waves cross the same bead without refilling it twice. */
    function clearBead(r, k) {
      var v = r.slots[k];
      if (v === null) return null;
      var a = r.angle + k * SLOT, x = px(a, r.rad), y = py(a, r.rad);
      var hex = D.colours[hueOf(v)];
      r.slots[k] = null;
      cleared++;
      blobs.push({ v: v, idx: r.idx, x: x, y: y, life: D.popTime });
      Fx.burst(x, y, { color: [hex, "#ffffff"], count: 9, speed: 250,
                       life: 0.45, grav: 90, size: 5 });
      /* The refill. ICE is seeded HERE and nowhere else — never on the
         opening board, which has to be read clean, and never through grant(),
         which hands out rewards. It rides in through the same door as every
         other bead, so the player watches the cold arrive and knows where. */
      var nc = drawColour(r);
      if (ICE_RATE > 0 && Rand.chance(ICE_RATE)) nc |= ICE;
      flyers.push({ ring: r, k: k, colour: nc,
                    t: -(D.fillDelay + r.idx * D.fillStagger),
                    dur: D.fillTime * (1 + (2 - r.idx) * 0.34),
                    x: x, y: y, a: 0 });
      return v;
    }

    /* A bead reached by a wave. It pays its own score and, if it was a super,
       sets off its own wave — that chain is the whole point, so every bead the
       chain reaches is worth more than the one before it. */
    function blowBead(r, k) {
      var v = clearBead(r, k);
      if (v === null) return;
      blastRun++;
      Eclipse.bead(r.idx);
      /* NOT multiplied by the SCORE window — see scoreHit. A wave's beads are
         already the biggest payout on this dial, and multiplying them is what
         put a bomb under an x10 thirteen times over the level next door. */
      var ramp = Math.min(1 + (blastRun - 1) * D.blastRamp, D.blastRampMax);
      var pts = Math.round(D.blastScore * Math.max(1, combo) * ramp);
      score += pts;
      blastGain += pts;
      HUD.setScore(score);
      Sound.clip("pop", 0.3, 1.25 + Rand.range(-0.1, 0.12));
      fireSuper(v, r, k, hueOf(v));
    }

    function fuse(r, k, delay) { fuses.push({ r: r, k: k, at: clock + delay }); }

    /* A power chain is over the moment no fuse is left burning — one wave, or
       a dozen supers setting each other off, it is one payout either way. It
       reports ONCE, at the hub the waves came from: a callout per bead would
       be a stream of noise over the very blast the player is watching. */
    function flushBlast() {
      if (blastRun > bestBlast) bestBlast = blastRun;
      if (blastRun >= D.blastCall)
        Pop.show("combo", { word: "Blast", sub: "+" + blastGain, cls: "blast",
                            at: { x: cx, y: cy } });
      blastRun = 0; blastGain = 0;
      Eclipse.blast();                   // a plate emptied whole buys daylight
    }

    /* A special going off. Everything here is reached the same way — the bead
       was cleared, and `v` is what it was carrying — so a power fires
       identically whether its own ray paid or another power's wave reached it.
       That single door is what makes eight specials chain into each other for
       free.

       `s` is the RAY the housing was sitting on, derived rather than passed:
       a plate stores its beads in its own frame, so the ray is `k + step`. Two
       of the powers need it and neither caller has it to hand. */
    function fireSuper(v, r, k, colour) {
      if (v & ICE) { iceHit(r); return; }          // the hazard, and it pays nothing
      if (!(v & BOON)) return;
      var s = mod(k + r.step, N);
      if (v & CHARGE)     ringBlast(r, k, colour);
      else if (v & NOVA)  novaBlast(r, k, colour);
      else if (v & BOMB)  bombBlast(r, k, colour);
      else if (v & FIRE)  fireBlast(r, k, colour, s);
      else if (v & LASER) beamBlast(r, k, colour, s);
      else if (v & SCORE) scoreHit(v, r, k);
      else if (v & SLOW)  slowHit(r, k);
    }

    /* A power names itself ONCE and in the clear band under the HUD, never at
       the hub: the hub is where flushBlast pays the whole chain out under one
       BLAST, and a name and a payout landing on the same pixel on the same
       beat is two things to read. Rate-limited for the same reason a cascade's
       COMBO is — one move can set off three powers inside a third of a second.

       CHARGE and NOVA say nothing, which is how they shipped: they are the two
       the player meets on levels 1 and 4 and they are self-evident on screen.
       The six below arrive one per level with nothing else new on it, and a
       name is what makes that lesson land. */
    var specCallAt = -9, specSaid = {};
    function specCall(word, hex) {
      /* A power names itself for the first `specTeach` of the round and then
         shuts up. The word is a LESSON, not a celebration — the level a power
         arrives on is the one where it is the only new thing, so three
         sightings is where a player has it; after that the same word over the
         same effect is noise on the beat they are watching the board. The
         effect itself never goes quiet: the wave, the flare and the payout are
         all still there. */
      if (clock - specCallAt < 0.45) return;
      var seen = (specSaid[word] || 0) + 1;
      specSaid[word] = seen;
      if (seen > D.specTeach) return;
      specCallAt = clock;
      Notify.say(word, { kind: "info", icon: "sparkles" });
      if (hex) Overlay.vignette(hex, 0.6, 360);
    }

    /* BOMB — the whole dial, and the supers it reaches go off in turn. The
       wave reaches each bead at the speed it would have travelled there, so
       the picture and the board can never disagree; it is the same contract
       every other wave here honours. */
    function bombBlast(r, k, colour) {
      var i, kk, aa, dx, dy;
      var a = r.angle + k * SLOT, ox = px(a, r.rad), oy = py(a, r.rad);
      for (i = 0; i < 3; i++) {
        for (kk = 0; kk < N; kk++) {
          if (rings[i].slots[kk] === null) continue;
          aa = rings[i].angle + kk * SLOT;
          dx = px(aa, rings[i].rad) - ox; dy = py(aa, rings[i].rad) - oy;
          fuse(rings[i], kk, Math.sqrt(dx * dx + dy * dy) / D.bombSpeed);
        }
      }
      booms.push({ x: ox, y: oy, t: 0, dur: 0.85, hex: D.colours[colour] });
      supers++;
      Sound.clip("blast", 0.7, 0.68);
      Fx.shake(26, 0.55);
      Fx.flash("#ffffff", 0.34, 2.6);
      specCall("Bomb", "#ffd43b");
    }

    /* FIRE — the two rays either side of its own. Both catch on the same beat:
       a stagger would read as two separate events, and the whole point of this
       one is that it takes a NEIGHBOURHOOD. */
    function fireBlast(r, k, colour, s) {
      var rays = [mod(s - 1, N), mod(s + 1, N)], i, j, rr, kk;
      for (i = 0; i < rays.length; i++) {
        for (j = 0; j < 3; j++) {
          rr = rings[j]; kk = mod(rays[i] - rr.step, N);
          fuse(rr, kk, D.fireDelay);
        }
        flares.push({ s: rays[i], hex: "#ff8a3d", life: D.flareTime * 1.3 });
      }
      supers++;
      Sound.clip("blast", 0.5, 1.22);
      Fx.shake(11, 0.3);
      specCall("Fire", "#ff8a3d");
    }

    /* LASER — straight through the hub and out the far side. `N / 2` is the
       ray opposite, which is only a whole ray because the dial has an even
       number of them; on an odd dial the floor picks the nearer of the two and
       the beam is drawn down the same line, so nothing here can desync. */
    function beamBlast(r, k, colour, s) {
      var opp = mod(s + Math.floor(N / 2), N), j, rr, kk;
      for (j = 0; j < 3; j++) {
        rr = rings[j]; kk = mod(opp - rr.step, N);
        fuse(rr, kk, D.laserDelay);
      }
      beams.push({ s: s, t: 0, dur: 0.45, hex: D.colours[colour] });
      flares.push({ s: opp, hex: D.colours[colour], life: D.flareTime * 1.3 });
      supers++;
      Sound.clip("nova", 0.5, 1.35);
      Fx.shake(9, 0.26);
      specCall("Laser", D.colours[colour]);
    }

    /* SCORE — the one power that touches no bead at all. It arms a multiplier
       for a few seconds, and the bigger the face the shorter it burns
       (D.mulTime), so an x10 is a window to SPEND rather than a number to bank.
       A second bead inside the window takes the bigger of the two faces and
       restarts its clock: stacking them would put x100 on a dial where the
       combo already multiplies everything once.

       IT MULTIPLIES THE RAYS THE PLAYER LINES UP, AND NOTHING ELSE — not the
       beads a wave takes, not a chain a power set off on its own. The scripted
       bench is what settled that, and the number was not close: with the window
       over everything, level 28 (bomb + score) paid 1.37M against level 27's
       101k — two adjacent levels in the same band, thirteen times apart, and
       no single objective line can serve both. The cause is arithmetic rather
       than tuning. A ray pays `rayScore * combo`; a bomb pays `blastScore *
       combo * ramp` across thirty-six beads, which is two orders of magnitude
       more before any multiplier touches it, so a window over the blast is a
       window over the whole round.

       Narrowing it to the rays also makes the two powers say different things.
       A bomb is the board cleared; a window is a few seconds where FINDING an
       alignment is worth ten of them. One is a payout, the other is a reason to
       play well while it burns — which is the only thing a multiplier on a
       match dial should ever be. */
    function scoreHit(v, r, k) {
      var tier = mulOf(v), face = D.mulSteps[tier] || 2, span = D.mulTime[tier] || 5;
      if (face >= mulK) { mulK = face; mulSpan = span; mulLeft = span; }
      else { mulLeft = Math.max(mulLeft, span); mulSpan = Math.max(mulSpan, mulLeft); }
      supers++;
      Sound.clip("multi", 0.6, 1 + tier * 0.08);
      Fx.flash("#ffd43b", 0.22, 1.9);
      Pop.show("record", { word: "x" + face, sub: "Score", at: "hudUnder" });
      specCallAt = clock;                 // ...and it counts as this beat's word
    }

    /* SLOW — the relief power, and the only one whose effect is on the room
       rather than on the board. It holds the eclipse's ink back; a CLASSIC
       round has no ink, so Eclipse.slow is a no-op there and the bead simply
       never reaches a pool that could hand it out. */
    function slowHit(r, k) {
      Eclipse.slow(D.slowTime);
      supers++;
      Sound.clip("charge", 0.55, 0.78);
      specCall("Slow", "#3ff0a0");
    }

    /* ICE — the hazard. Breaking it freezes the plate it sat on: that ring
       cannot be turned until `iceRays` more rays have paid, or `iceTime`
       seconds have gone by, whichever comes first.

       The clock is not decoration. A board where no ray can pay would leave a
       plate locked for the rest of the round, and `iceMax` is the other half
       of the same guard: the cold may hold TWO plates and never all three, so
       there is always a ring left to turn. Two frozen and one free is the
       interesting constraint; three frozen is a round the player watches. */
    function iceHit(r) {
      var i, held = 0;
      for (i = 0; i < 3; i++) if (rings[i].cold > 0) held++;
      if (r.cold <= 0 && held >= D.iceMax) return;
      r.cold = D.iceRays; r.coldT = D.iceTime;
      if (grab && grab.ring === r) grab = null;      // the finger loses it mid-turn
      Sound.clip("tick", 0.5, 0.42);
      Fx.ring(cx, cy, { from: r.rad - r.band / 2, to: r.rad + r.band / 2,
                        color: "#9fdcff", width: r.band * 0.6, life: 0.35 });
      Overlay.vignette("#9fdcff", 0.7, 420);
      Pop.show("danger", { word: "Frozen", sub: r.cold + Lang.t(" rays"), at: "hudUnder" });
      specCallAt = clock;
    }

    function thaw(r) {
      r.cold = 0; r.coldT = 0;
      Sound.clip("land", 0.35, 1.3);
      Fx.ring(cx, cy, { from: r.rad + r.band / 2, to: r.rad - r.band / 2,
                        color: "#ffffff", width: r.band * 0.5, life: 0.3 });
    }

    /* CHARGE — the wave leaves its own housing and runs both ways around the
       plate, one housing every `fuseStep`, so the ring visibly unzips. */
    function ringBlast(r, k, colour) {
      var j, half = Math.floor(N / 2);
      for (j = 1; j <= half; j++) {
        fuse(r, mod(k + j, N), j * D.fuseStep);
        if (j < half || N % 2) fuse(r, mod(k - j, N), j * D.fuseStep);
      }
      sweeps.push({ ring: r, k: k, t: 0, travel: half * D.fuseStep,
                    dur: half * D.fuseStep + 0.18, hex: D.colours[colour] });
      supers++;
      Sound.clip("blast", 0.6);
      Fx.shake(15, 0.36);
      // No callout of its own: the wave IS the spectacle, and flushBlast pays
      // the whole chain out under one BLAST once the last fuse has burnt.
    }

    /* NOVA — every bead of the ray's colour goes, the wave reaching each one at
       the speed it would have travelled there from the nova's own housing. */
    function novaBlast(r, k, colour) {
      var i, kk, v, aa, dx, dy;
      var a = r.angle + k * SLOT, ox = px(a, r.rad), oy = py(a, r.rad);
      for (i = 0; i < 3; i++) {
        for (kk = 0; kk < N; kk++) {
          v = rings[i].slots[kk];
          if (v === null || hueOf(v) !== colour) continue;
          aa = rings[i].angle + kk * SLOT;
          dx = px(aa, rings[i].rad) - ox; dy = py(aa, rings[i].rad) - oy;
          fuse(rings[i], kk, Math.sqrt(dx * dx + dy * dy) / D.novaSpeed);
        }
      }
      novas.push({ x: ox, y: oy, t: 0, dur: 0.6, hex: D.colours[colour] });
      supers++;
      Sound.clip("nova", 0.6);
      Fx.shake(18, 0.42);
      Fx.flash("#ffffff", 0.28, 2.2);
      Overlay.vignette(D.colours[colour], 0.9, 520);
      // No callout: NOVA is the name of a FOUR-RAY move now (see pop), and the
      // payout of the chain this starts is announced once by flushBlast.
    }

    /* Earning a super. It is not dropped on the board out of nowhere: one of
       the refills already flying in from the rim is upgraded, so the reward
       arrives through the same door every other bead does — and the player
       watches it land and knows where it is. */
    /* Supers already on the dial, housings and refills in flight alike. A
       CHARGE only goes off when its own colour lines up on its own ray, so
       without a cap they pile up: measured, six crowns on the board at once,
       which both looks like noise and makes each one worth nothing. Over the
       cap the meter simply stays full and pays out the moment a super fires. */
    function liveSupers() {
      var n = 0, i, k;
      // BOON and not SUPER: an ICE bead is a hazard the board threw at the
      // player, and letting it fill a reward slot would make a frozen dial pay
      // less as well as turn less.
      for (i = 0; i < 3; i++)
        for (k = 0; k < N; k++) if (rings[i].slots[k] & BOON) n++;
      for (i = 0; i < flyers.length; i++) if (flyers[i].colour & BOON) n++;
      return n;
    }

    /* Earning a special. It is not dropped on the board out of nowhere: one of
       the refills already flying in from the rim is upgraded, so the reward
       arrives through the same door every other bead does — and the player
       watches it land and knows where it is.

       WHICH special comes out of the LEVEL, never out of the code: `tier` says
       how big the beat was (1 for a two-ray move or a x4 chain, 2 for a
       three-ray move or a x8 chain) and the level's own `pool` says what a big
       or a small beat pays in. A level whose pool has no big special pays its
       big beats in small ones rather than reaching outside the level for
       something the player has not met yet — which is the entire reason the
       first three levels can be CHARGE and nothing else. */
    function grant(tier, colour) {
      if (liveSupers() >= D.superCap) return false;
      var keys = [], cand = [], i, sp, v, bit;
      for (i = 0; i < POOL.length; i++) {
        sp = SPEC[POOL[i]];
        if (sp && sp.tier === tier) keys.push(POOL[i]);
      }
      if (!keys.length && tier > 1)
        for (i = 0; i < POOL.length; i++) {
          sp = SPEC[POOL[i]];
          if (sp && sp.tier === 1) keys.push(POOL[i]);
        }
      if (!keys.length) return false;
      for (i = 0; i < flyers.length; i++) if (!(flyers[i].colour & SUPER)) cand.push(i);
      if (!cand.length) return false;
      bit = SPEC[Rand.pick(keys)].bit;
      // A NOVA belongs to no colour, so it takes one at random and its hue is
      // only what it PAYS in; everything else takes the colour of the ray that
      // earned it, which is the colour it will have to line up on to go off.
      v = (bit === NOVA ? Rand.int(0, palette.length - 1) : colour) | bit;
      // The score bead's face climbs with the level: x2 low down, x10 only
      // where the round is long enough to spend a four-second window.
      if (bit === SCORE) v |= Rand.int(0, MUL_FACE - 1) << MULSHIFT;
      flyers[Rand.pick(cand)].colour = v;
      Sound.clip("charge", 0.5, bit === NOVA ? 1.12 : 1);
      return true;
    }

    /* Everything a paid ray does: empty its three housings, set off whatever
       supers were sitting on it, throw the juice and move the chain on. Two
       rays in one move is the skill beat of the game, so it earns a super.

       `cascade` is true when the board paid on its own — a refill landing on a
       ray of its own, seconds after the finger left the plate. It is the one
       thing a callout has to separate from a move, because the player did not
       aim it, so it reads as the machine paying them back: those pops say
       COMBO, whatever the ray count. ONE callout leaves this function, in the
       clear band under the HUD, and only a lone deliberate ray gets the
       positional `+pts` on the dial instead — three of those under a TRIPLE
       RAY banner is three things to read on the beat the player is looking at
       the beads. */
    function pop(hits, cascade) {
      var i, j, s, k, r, a, v, hex, colour = 0, pts, gained = 0;
      for (i = 0; i < hits.length; i++) {
        s = hits[i];
        colour = rayColour(s);
        hex = D.colours[colour];
        matches++;
        Eclipse.line();                      // ...which is this mode's "line"
        charge++;
        combo = Math.min(combo + 1, D.comboMax);
        if (combo > bestCombo) bestCombo = combo;
        comboLeft = D.comboWindow;
        // The SCORE bead's window multiplies the ray at source, so the "+pts"
        // that floats over the beads is the number actually banked.
        pts = Math.round(D.rayScore * combo * mulK);
        gained += pts;
        for (j = 0; j < 3; j++) {
          r = rings[j];
          k = mod(s - r.step, N);
          v = clearBead(r, k);
          fireSuper(v, r, k, colour);          // the ray's colour, not the bead's
        }
        flares.push({ s: s, hex: hex, life: D.flareTime });
        if (hits.length === 1 && !cascade) {
          a = s * SLOT;
          Pop.show("score", { word: "+" + pts,
                              at: { x: px(a, rings[1].rad), y: py(a, rings[1].rad) } });
        }
        Sound.clip("pop", 0.5, 1 + Math.min(combo, 8) * 0.05);
      }

      if (hits.length > 1) {
        multis++;
        // The move is multiplied, not topped up: `gained` still holds only
        // what the rays themselves paid, chain included.
        var mult = D.multiMult[Math.min(hits.length, D.multiMult.length) - 1];
        var bonus = Math.round(gained * (mult - 1));
        gained += bonus;
        Sound.clip("multi", 0.55);
        Fx.shake(12, 0.3);
        Overlay.vignette(D.colours[colour], 0.75, 420);
        grant(hits.length > 2 ? 2 : 1, colour);
        Eclipse.multi(hits.length);      // ...and pushes the shadow back
      } else {
        Fx.shake(4 + combo * 0.4, 0.16);
        Eclipse.single();                // one ray only freezes it
      }

      score += gained;
      HUD.setScore(score);
      HUD.punch(combo >= 8 ? "#ffd43b" : D.colours[colour]);

      /* The move's one callout, named after what the player did: a cascade is
         COMBO, two rays a DOUBLE, three a TRIPLE, four or more a NOVA. Two
         rays is frequent enough that it must not blanket the dial the finger
         is still on, so everything but the four-ray beat stays in the clear
         band under the HUD. */
      if (cascade) {
        if (clock - comboCallAt >= D.comboCall) {
          comboCallAt = clock;
          Pop.show("combo", { word: "Combo", sub: "x" + combo, at: "hudUnder" });
        }
      } else if (hits.length >= 4)
        Pop.show("ultra", { word: "Nova", sub: "+" + gained, at: "bottom" });
      else if (hits.length === 3)
        Pop.show("ribbon", { word: "Triple ray", sub: "+" + gained, at: "hudUnder" });
      else if (hits.length === 2)
        Pop.show("bonus", { word: "Double ray", sub: "+" + gained, at: "hudUnder" });

      /* Every ray paid is a ray off a frozen plate's debt. It is counted per
         RAY and not per move, so a double unfreezes twice as fast as a single
         — the ice is answered by playing well, which is the only currency this
         dial has. */
      for (j = 0; j < 3; j++) {
        if (rings[j].cold <= 0) continue;
        rings[j].cold -= hits.length;
        if (rings[j].cold <= 0) thaw(rings[j]);
      }

      // The meter on the hub: every ray banks a notch, and a full meter buys a
      // small special. It is the floor under the whole reward curve — a player
      // who never lines up two rays at once still gets one every few moves,
      // and gets to watch it coming.
      if (charge >= D.chargeNeed && grant(1, colour)) charge = 0;

      // Milestones: every fourth link of the chain, up to the cap. The chain is
      // the other way to earn a super, so a long clean run pays a big one. It
      // has no callout of its own — the chain is what the COMBO pop already
      // reads out, and the score counter races up on the same beat.
      if (combo >= 4 && combo % 4 === 0) {
        score += Math.round(D.comboBonus * combo * mulK);
        HUD.setScore(score);
        Sound.clip("chain", 0.5, 1 + combo * 0.02);
        grant(combo >= 8 ? 2 : 1, colour);
      }
    }

    /* The fifth hue joins the dial at level 10 (D.colourUpLevel), which is 90
       fused rays in: rays get rarer, so a long run is played with the ring you
       already know rather than by sweeping. */
    function addColour() {
      palette.push(palette.length);
      for (var i = 0; i < 3; i++) rings[i].bag.length = 0;   // re-deal with the newcomer in
      Pop.show("bonus", { word: "New colour", sub: "Rays get rarer", at: "bottom" });
      Overlay.vignette(D.colours[palette.length - 1], 0.7, 500);
      Sound.clip("multi", 0.45, 0.9);
    }

    // --- input: one finger, one plate --------------------------------------
    function ringAt(d) {
      for (var i = 0; i < 3; i++) if (d >= rings[i].inner && d < rings[i].outer) return rings[i];
      return null;
    }
    function pang(p) { return Math.atan2(p.x - cx, cy - p.y); }

    function onDown(p) {
      if (finale) return;                     // the clock is out: finish the move, start no other
      var dx = p.x - cx, dy = p.y - cy;
      var r = ringAt(Math.sqrt(dx * dx + dy * dy));
      if (!r) return;
      /* A frozen plate refuses the finger, and says so where the finger is —
         the plate is already drawn in frost, but a player reaching for it is
         reading their own thumb, not the dial. */
      if (r.cold > 0) {
        Pop.text(p.x, p.y, "Frozen", { color: "#9fdcff", size: 22, life: 0.6, tier: 1 });
        Sound.clip("tick", 0.35, 0.48);
        return;
      }
      grab = { ring: r, last: pang(p) };
      touched = true;
      Sound.clip("tick", 0.2, 0.85);
    }

    function onMove(p) {
      if (!grab) return;
      var a = pang(p);
      grab.ring.angle += wrap(a - grab.last);
      grab.last = a;
      syncStep(grab.ring);
    }

    function onUp() { grab = null; }

    // --- lifecycle ---------------------------------------------------------
    function reset() {
      var i;
      // Which mode this round runs in, before anything is sized or seeded.
      Eclipse.arm();

      /* THE WORLD'S HALL AND ITS BED, moved together (ladder.biomes). BIO was
         fixed by applyLevel() a moment ago, which is why both of these are one
         line here and nothing has to recompute the level. The playable and the
         endless run have no world: they keep the scene they ship and play all
         of the one window they embed, which is what `null` asks for. */
      if (BIO) Art.backdrop(BIO.scene);
      Music.play(CONFIG.level && BIO ? BIO.music : null);
      score = 0; matches = 0; multis = 0; supers = 0; cleared = 0;
      combo = 0; bestCombo = 0; comboLeft = 0; charge = 0; comboCallAt = -9;
      blastRun = 0; blastGain = 0; bestBlast = 0;
      clock = 0; grab = null; touched = false; resting = true; armed = null;
      finale = null;
      mulK = 1; mulLeft = 0; mulSpan = 1; specCallAt = -9; specSaid = {};
      for (i = 0; i < 3; i++) {
        rings[i].prev = 0; rings[i].still = 9;
        rings[i].cold = 0; rings[i].coldT = 0;
      }
      flyers = []; blobs = []; flares = [];
      fuses = []; sweeps = []; novas = []; booms = []; beams = [];
      palette = [];
      for (i = 0; i < D.startColours; i++) palette.push(i);
      layout();
      seed();
      best = Store.get("bestScore", 0);
      HUD.setScoreNow(0);
      HUD.setLeft(best, "Best");
      Fx.reset();
      Eclipse.reset();
    }

    function onResize() { layout(); }

    function update(dt) {
      var i, r, f, t, p, e, a, rad;
      clock += dt;

      // A plate the finger is not holding clicks onto its nearest housing.
      for (i = 0; i < 3; i++) {
        r = rings[i];
        if (grab && grab.ring === r) continue;
        t = Math.round(r.angle / SLOT) * SLOT;
        r.angle += (t - r.angle) * Math.min(1, dt * D.snap);
        syncStep(r);
      }
      for (i = 0; i < 3; i++) tickRest(rings[i], dt);

      // The eclipse sweeps BEFORE the board is read, so the preview and the
      // payout of this frame both see the same shadow.
      if (Eclipse.on) Eclipse.update(dt);

      // The dial pays on the frame it comes to rest, not on the way there.
      var rest = settled();
      if (rest && !resting) resolve();
      resting = rest;
      armed = rest ? null : scan();          // the preview, only while turning

      // ...and on the frame the shadow lets a ray go: the dial has not moved,
      // so this is the only re-read that will ever happen.
      if (rest && Eclipse.uncovered()) resolve();

      // Refills, riding in from outside the rim. Their angle is read off the
      // ring every frame, so turning a plate mid-refill carries its incoming
      // beads around with it instead of dropping them in the wrong housing.
      for (i = flyers.length - 1; i >= 0; i--) {
        f = flyers[i];
        f.t += dt;
        if (f.t < 0) continue;
        p = f.t / f.dur;
        a = f.ring.angle + f.k * SLOT;
        if (p >= 1) {
          f.ring.slots[f.k] = f.colour;
          flyers.splice(i, 1);
          Sound.clip("land", 0.2, 1.16 - f.ring.idx * 0.13);
          Fx.ring(px(a, f.ring.rad), py(a, f.ring.rad),
                  { from: f.ring.ballR * 0.5, to: f.ring.ballR * 1.8,
                    color: D.colours[f.colour], width: 3, life: 0.22 });
          if (settled()) resolve(true);        // the cascade, if nothing moved
          continue;
        }
        e = 1 - (1 - p) * (1 - p);                  // decelerates into the housing
        rad = unit * D.fillFrom + (f.ring.rad - unit * D.fillFrom) * e;
        f.x = px(a, rad); f.y = py(a, rad);
        f.a = clamp(p * 3, 0, 1);
      }

      // Waves reaching the beads they were aimed at. A bead that goes off here
      // may light a fuse of its own, which is appended and burns next.
      for (i = fuses.length - 1; i >= 0; i--) {
        if (clock < fuses[i].at) continue;
        f = fuses[i];
        fuses.splice(i, 1);
        blowBead(f.r, f.k);
      }
      // Every wave has burnt out: settle the chain and pay it its callout.
      if (!fuses.length && blastRun) flushBlast();

      for (i = blobs.length - 1; i >= 0; i--) {
        blobs[i].life -= dt;
        if (blobs[i].life <= 0) blobs.splice(i, 1);
      }
      for (i = sweeps.length - 1; i >= 0; i--) {
        sweeps[i].t += dt;
        if (sweeps[i].t >= sweeps[i].dur) sweeps.splice(i, 1);
      }
      for (i = novas.length - 1; i >= 0; i--) {
        novas[i].t += dt;
        if (novas[i].t >= novas[i].dur) novas.splice(i, 1);
      }
      for (i = booms.length - 1; i >= 0; i--) {
        booms[i].t += dt;
        if (booms[i].t >= booms[i].dur) booms.splice(i, 1);
      }
      for (i = beams.length - 1; i >= 0; i--) {
        beams[i].t += dt;
        if (beams[i].t >= beams[i].dur) beams.splice(i, 1);
      }
      for (i = flares.length - 1; i >= 0; i--) {
        flares[i].life -= dt;
        if (flares[i].life <= 0) flares.splice(i, 1);
      }

      // A chain only lives as long as the player keeps paying rays.
      if (combo > 0) { comboLeft -= dt; if (comboLeft <= 0) combo = 0; }

      // The SCORE bead's window, and the cold. The ice thaws on RAYS (see pop)
      // and this is only its safety net: a board that cannot pay must never
      // leave a plate locked for the rest of the round.
      if (mulLeft > 0) { mulLeft -= dt; if (mulLeft <= 0) { mulLeft = 0; mulK = 1; } }
      for (i = 0; i < 3; i++) {
        if (rings[i].cold <= 0) continue;
        rings[i].coldT -= dt;
        if (rings[i].coldT <= 0) thaw(rings[i]);
      }

      // The eclipse has levels, so the newcomer is scheduled on one; a CLASSIC
      // round never reaches level 10 in 40 seconds and keeps its stopwatch.
      if (palette.length < D.colours.length &&
          (Eclipse.on ? Eclipse.level() >= D.colourUpLevel
                      : Round.elapsed() >= D.colourUpAt)) addColour();

      // The clock is out: wait for the dial, then play the machine out.
      if (finale) stepFinale(dt);
    }

    // --- drawing -----------------------------------------------------------
    function drawBall(v, idx, x, y, sc, alpha) {
      var sp = (v & NOVA) ? novaBodies[idx] : sprites[hueOf(v)][idx];
      var w = sp.width * sc;
      if (alpha < 1) ctx.globalAlpha = alpha;
      if (v & NOVA && !ART_ON) {
        // the drawn spectrum spins, its lighting stays put — see novaBody
        ctx.save();
        ctx.translate(x, y);
        ctx.rotate(novaAngle());
        ctx.drawImage(sp, -w / 2, -w / 2, w, w);
        ctx.restore();
        ctx.drawImage(novaShells[idx], x - w / 2, y - w / 2, w, w);
      } else {
        ctx.drawImage(sp, x - w / 2, y - w / 2, w, w);
      }
      if (v & SUPER) drawBadge(v, rings[idx].ballR * sc, x, y);
      // A bead the ink has reached is sunk into it — still perfectly legible,
      // just plainly not in play. One flat disc over the sprite: it keeps the
      // enamel's shape instead of washing the bead out with globalAlpha.
      // It is measured on the BEAD, not on the sprite: the materials pad their
      // canvases by 22% for the sticker's shadow and the ink's wobble, and a
      // veil that wide would sink the housings either side of this one too.
      var d = Eclipse.sink(x, y);
      if (d > 0) {
        ctx.fillStyle = rgba("#04030a", 0.44 * d * alpha);
        ctx.beginPath(); ctx.arc(x, y, rings[idx].ballR * sc * 1.04, 0, TAU); ctx.fill();
      }
      if (alpha < 1) ctx.globalAlpha = 1;
    }

    /* --- WHAT TELLS A SPECIAL APART, at a glance and with no legend --------
       Eight beads that all have to be read in the second before a finger
       moves, on a dial whose whole gameplay is the COLOUR underneath them.
       Three rules, and between them they are the reason this stayed readable
       when it went from two specials to eight:

         1. THE HUE IS NEVER TOUCHED. Every badge is drawn OVER the bead's own
            material, never instead of it. A special only goes off when its
            colour lines up on its ray, so a bead whose colour you cannot read
            is a bead you cannot plan with. The one exception is the NOVA,
            which belongs to no colour at all and therefore has none to hide.
         2. THE SHAPE SAYS WHICH, THE RIM SAYS WHETHER. Every boon wears the
            SAME gold breathing rim — that is "there is something here", legible
            on the inner plate where the bead is 22 px across and the glyph is
            barely 12. The silhouette inside it is what says which one, and the
            eight silhouettes were chosen to share no outline: concentric
            rings, a starburst, a two-headed arrow, a flame, two digits, an
            hourglass, a six-spoke flake, and — for the nova — nothing at all.
         3. WHITE ON A DOUBLE PASS OF INK. Every glyph is drawn twice, a wide
            near-black pass under a white one, so it holds on the amber and the
            cyan exactly as it does on the violet. One ink colour for all of
            them means the eye never has to ask what a glyph's COLOUR meant, on
            a board where colour already means something else.

       The gold is the badge and the white is the glyph, and neither collides
       with the white HALO of an armed ray: that halo is a ring drawn AROUND
       the bead with a bar down its ray, this sits inside it.

       ICE is the exception to the rim, and deliberately so: it is the one bead
       the player does not want, so it wears a pale frost crust and a cold rim
       instead of the gold. Gold on this dial means a reward.

       Only a handful are ever on the board at once (D.superCap), so all of
       this can afford to be drawn live where the beads themselves cannot. */
    function drawBadge(v, r, x, y) {
      /* The glyph is 46% of the radius and not a pixel more. It was 54% on the
         first sheet and the contact print settled it: on the sticker biome —
         whose body is only 79% of the bead to start with — a glyph that wide
         leaves the hue as a rim, and the hue is what the player is actually
         matching. The badge has to be the second thing read, never the first. */
      var i, t, rr, s = r * 0.46, lw = Math.max(1.5, r * 0.105);

      /* A path drawn twice: a wide near-black pass, then the colour. It is
         what makes one white glyph work over five hues and six materials. */
      function stroked(build, col) {
        ctx.lineCap = "round"; ctx.lineJoin = "round";
        build();
        ctx.lineWidth = lw * 2.5; ctx.strokeStyle = rgba("#070414", 0.6); ctx.stroke();
        ctx.lineWidth = lw;       ctx.strokeStyle = col;                  ctx.stroke();
      }
      function filled(build, col) {
        ctx.lineJoin = "round";
        build();
        ctx.lineWidth = lw * 2.0; ctx.strokeStyle = rgba("#070414", 0.6); ctx.stroke();
        ctx.fillStyle = col; ctx.fill();
      }

      ctx.save();
      ctx.translate(x, y);

      /* NOVA — no shape at all. Its body already turns through every colour
         (see novaBody), so a glyph on top would blur the one distinction the
         player has to make in a glance. A white rim, breathing. */
      if (v & NOVA) {
        t = 0.30 + 0.45 * (0.5 + 0.5 * Math.sin(clock * 3.2));
        ctx.lineWidth = Math.max(1.2, r * 0.055);
        ctx.strokeStyle = rgba("#ffffff", t);
        ctx.beginPath(); ctx.arc(0, 0, r * 1.13, 0, TAU); ctx.stroke();
        ctx.restore();
        return;
      }

      /* ICE — a crust of frost over the bead and a cold rim. No gold: this is
         the one bead on the dial that costs the player something. */
      if (v & ICE) {
        /* The crust is light on purpose. An ICE bead MATCHES like any other —
           it is a normal bead that punishes the plate it breaks on — so
           whitening it until its hue is gone would cost the player the move,
           not just the plate. */
        ctx.fillStyle = rgba("#cfeeff", 0.17);
        ctx.beginPath(); ctx.arc(0, 0, r * 0.93, 0, TAU); ctx.fill();
        t = 0.45 + 0.30 * (0.5 + 0.5 * Math.sin(clock * 2.4));
        ctx.lineWidth = Math.max(1.4, r * 0.10);
        ctx.strokeStyle = rgba("#9fdcff", t);
        ctx.beginPath(); ctx.arc(0, 0, r * 1.02, 0, TAU); ctx.stroke();
        stroked(function () {                      // the six-spoke flake
          var j, a, fs = s * 0.86;
          ctx.beginPath();
          for (j = 0; j < 3; j++) {
            a = j * Math.PI / 3;
            ctx.moveTo(-Math.cos(a) * fs, -Math.sin(a) * fs);
            ctx.lineTo(Math.cos(a) * fs, Math.sin(a) * fs);
          }
          for (j = 0; j < 6; j++) {                // ...and its barbs
            a = j * Math.PI / 3;
            var bx = Math.cos(a) * fs * 0.58, by = Math.sin(a) * fs * 0.58;
            ctx.moveTo(bx, by);
            ctx.lineTo(bx + Math.cos(a + 0.9) * fs * 0.34, by + Math.sin(a + 0.9) * fs * 0.34);
            ctx.moveTo(bx, by);
            ctx.lineTo(bx + Math.cos(a - 0.9) * fs * 0.34, by + Math.sin(a - 0.9) * fs * 0.34);
          }
        }, "#eaf8ff");
        ctx.restore();
        return;
      }

      // Every boon wears the same gold rim: "there is something here", read
      // before the glyph inside it can be.
      t = 0.55 + 0.35 * (0.5 + 0.5 * Math.sin(clock * 3.2));
      ctx.lineWidth = Math.max(1.4, r * 0.085);
      ctx.strokeStyle = rgba("#ffd43b", t);
      ctx.beginPath(); ctx.arc(0, 0, r * 1.08, 0, TAU); ctx.stroke();

      if (v & CHARGE) {
        /* CONCENTRIC RINGS, and two more crawling out of them half a cycle
           apart. The target says "armed", the rings leaving it say what it
           does — the blast travels AWAY from this housing, round the plate,
           both ways at once. */
        stroked(function () {
          ctx.beginPath(); ctx.arc(0, 0, s * 0.92, 0, TAU);
          ctx.moveTo(s * 0.48, 0); ctx.arc(0, 0, s * 0.48, 0, TAU);
        }, "#ffffff");
        ctx.fillStyle = "#ffffff";
        ctx.beginPath(); ctx.arc(0, 0, Math.max(1.4, s * 0.17), 0, TAU); ctx.fill();
        for (i = 0; i < 2; i++) {
          t = mod(clock / D.chargePing + i * 0.5, 1);
          rr = r * (0.92 + t * 0.45);            // stops short of the next housing
          ctx.lineWidth = Math.max(1.4, r * 0.10 * (1 - t));
          ctx.strokeStyle = rgba("#ffd43b", 0.7 * (1 - t));
          ctx.beginPath(); ctx.arc(0, 0, rr, 0, TAU); ctx.stroke();
        }
      } else if (v & BOMB) {
        /* A STARBURST — sixteen points alternating long and short. It is the
           only glyph here with spikes, and it is the only power that reaches
           every bead on the board: the silhouette says "in all directions"
           before the player has ever seen one go off. */
        filled(function () {
          var j, a, rr2;
          ctx.beginPath();
          for (j = 0; j < 16; j++) {
            a = j * TAU / 16 - Math.PI / 2;
            rr2 = (j % 2) ? s * 0.42 : s;
            if (j) ctx.lineTo(Math.cos(a) * rr2, Math.sin(a) * rr2);
            else   ctx.moveTo(Math.cos(a) * rr2, Math.sin(a) * rr2);
          }
          ctx.closePath();
        }, "#ffffff");
      } else if (v & LASER) {
        /* A TWO-HEADED ARROW, turned to lie ALONG its own ray. The beam goes
           straight through the hub and out the far side, so the glyph points
           at the two ends of the line it is about to fire down — which is the
           one thing about this power that is not guessable from a word. */
        ctx.save();
        ctx.rotate(Math.atan2(x - cx, cy - y));
        stroked(function () {
          var h = s * 0.42;
          ctx.beginPath();
          ctx.moveTo(0, -s); ctx.lineTo(0, s);
          ctx.moveTo(-h, -s + h); ctx.lineTo(0, -s); ctx.lineTo(h, -s + h);
          ctx.moveTo(-h, s - h); ctx.lineTo(0, s); ctx.lineTo(h, s - h);
        }, "#ffffff");
        ctx.restore();
      } else if (v & FIRE) {
        /* A FLAME, and it took three goes at the contact sheet before it was
           one. A symmetric teardrop read as a LEAF; the same teardrop with one
           asymmetric curl down its left side read as a WATER DROP, which is
           worse — the only glyph here named after what it does, saying the
           opposite of it.

           What settles it is not the outline, it is the COUNT: three tongues
           over two valleys. A single peak is a drop at any size and a flame at
           none, and no amount of wobble on the flanks changes that. The three
           peaks survive being drawn 10 px across on the inner plate, which is
           the only size that was ever in question.

           The two rays it takes are its neighbours, and the first one the
           player sets off teaches that in half a second. The glyph's whole job
           is to be unmistakably FIRE before then. */
        filled(function () {
          ctx.beginPath();
          ctx.moveTo(s * 0.04, -s);                                   // the tall tongue
          ctx.quadraticCurveTo(s * 0.30, -s * 0.58, s * 0.34, -s * 0.30);
          ctx.quadraticCurveTo(s * 0.44, -s * 0.64, s * 0.62, -s * 0.44);  // right tongue
          ctx.quadraticCurveTo(s * 0.88, -s * 0.06, s * 0.60, s * 0.44);
          ctx.quadraticCurveTo(s * 0.36, s * 0.96, -s * 0.04, s * 0.96);   // the base
          ctx.quadraticCurveTo(-s * 0.48, s * 0.96, -s * 0.62, s * 0.40);
          ctx.quadraticCurveTo(-s * 0.82, -s * 0.06, -s * 0.56, -s * 0.44); // left tongue
          ctx.quadraticCurveTo(-s * 0.48, -s * 0.66, -s * 0.36, -s * 0.30);
          ctx.quadraticCurveTo(-s * 0.26, -s * 0.62, s * 0.04, -s);
          ctx.closePath();
        }, "#ffffff");
      } else if (v & SCORE) {
        /* THE NUMBER ITSELF. Every other glyph is a picture standing in for a
           word; this one IS the word, and no picture of a multiplier beats
           reading "x10". The x10 face is set narrower so the three glyphs cost
           the same width on the inner plate. */
        var face = D.mulSteps[mulOf(v)] || 2;
        var txt = "x" + face;
        ctx.font = "900 " + Math.round(r * (face >= 10 ? 0.74 : 0.92)) + "px " +
                   "-apple-system,BlinkMacSystemFont,Segoe UI,sans-serif";
        ctx.textAlign = "center"; ctx.textBaseline = "middle";
        ctx.lineJoin = "round";
        ctx.lineWidth = lw * 2.2; ctx.strokeStyle = rgba("#070414", 0.7);
        ctx.strokeText(txt, 0, r * 0.04);
        ctx.fillStyle = "#ffffff";
        ctx.fillText(txt, 0, r * 0.04);
      } else if (v & SLOW) {
        // AN HOURGLASS — the two caps are what stop it reading as a bowtie,
        // and they are worth the two extra lines.
        filled(function () {
          ctx.beginPath();
          ctx.moveTo(-s * 0.62, -s * 0.74); ctx.lineTo(s * 0.62, -s * 0.74);
          ctx.lineTo(0, 0); ctx.closePath();
          ctx.moveTo(-s * 0.62, s * 0.74); ctx.lineTo(s * 0.62, s * 0.74);
          ctx.lineTo(0, 0); ctx.closePath();
        }, "#ffffff");
        stroked(function () {
          ctx.beginPath();
          ctx.moveTo(-s * 0.80, -s * 0.86); ctx.lineTo(s * 0.80, -s * 0.86);
          ctx.moveTo(-s * 0.80, s * 0.86); ctx.lineTo(s * 0.80, s * 0.86);
        }, "#ffffff");
      }
      ctx.restore();
    }

    function drawPlate(r) {
      var held = grab && grab.ring === r;
      // Before the first touch the outer plate breathes, so it is obvious
      // which part of the dial is asking for a finger.
      var call = (!touched && r.idx === 2) ? 0.18 * (0.5 + 0.5 * Math.sin(clock * 4)) : 0;
      ctx.lineWidth = r.band;
      ctx.strokeStyle = rgba(D.plate, 0.5 + (held ? 0.22 : 0));
      ctx.beginPath(); ctx.arc(cx, cy, r.rad, 0, TAU); ctx.stroke();
      ctx.lineWidth = 2;
      ctx.strokeStyle = rgba(D.wire, 0.46 + (held ? 0.4 : 0) + call);
      ctx.beginPath(); ctx.arc(cx, cy, r.rad - r.band / 2, 0, TAU); ctx.stroke();
      ctx.beginPath(); ctx.arc(cx, cy, r.rad + r.band / 2, 0, TAU); ctx.stroke();
      /* Frost, on the PLATE and not on its beads. The beads are what the
         player reads to plan the move they will make once it thaws, so they
         stay at full colour; the track under them goes cold and its two walls
         go white, which is the same trick the eclipse uses to say "this part
         of the machine is out" without hiding anything. */
      if (r.cold > 0) {
        var ph = 0.5 + 0.5 * Math.sin(clock * 2.4);
        ctx.lineWidth = r.band;
        ctx.strokeStyle = rgba("#9fdcff", 0.15 + 0.07 * ph);
        ctx.beginPath(); ctx.arc(cx, cy, r.rad, 0, TAU); ctx.stroke();
        ctx.lineWidth = 3;
        ctx.strokeStyle = rgba("#dff6ff", 0.45 + 0.28 * ph);
        ctx.beginPath(); ctx.arc(cx, cy, r.rad - r.band / 2, 0, TAU); ctx.stroke();
        ctx.beginPath(); ctx.arc(cx, cy, r.rad + r.band / 2, 0, TAU); ctx.stroke();
      }
    }

    /* The teeth belong to the outer plate, so they turn with it: one path,
       one fill, 2N trapezoids between the housing track and the rim. */
    function drawTeeth(r) {
      var n = N * 2, w = TAU / n * 0.42, i, a;
      var r0 = r.rad + r.band / 2, r1 = rimR;
      ctx.fillStyle = rgba(D.wire, 0.5 + (grab && grab.ring === r ? 0.2 : 0));
      ctx.beginPath();
      for (i = 0; i < n; i++) {
        a = r.angle + i * (TAU / n);
        ctx.moveTo(px(a - w, r0), py(a - w, r0));
        ctx.lineTo(px(a - w * 0.55, r1), py(a - w * 0.55, r1));
        ctx.lineTo(px(a + w * 0.55, r1), py(a + w * 0.55, r1));
        ctx.lineTo(px(a + w, r0), py(a + w, r0));
        ctx.closePath();
      }
      ctx.fill();
    }

    function drawArmed(s, alpha) {
      var hex = D.colours[rayColour(s)], w = unit * 0.075, i, r, a;
      ctx.save();
      ctx.translate(cx, cy); ctx.rotate(s * SLOT);
      var g = ctx.createLinearGradient(0, -hubR, 0, -rimR);
      g.addColorStop(0, rgba(hex, 0));
      g.addColorStop(0.5, rgba(hex, alpha));
      g.addColorStop(1, rgba(hex, 0));
      ctx.fillStyle = g;
      ctx.fillRect(-w / 2, -rimR, w, rimR - hubR);
      ctx.restore();
      // a halo on each of the three beads, so the ray is legible even where
      // the beads themselves cover the bar
      ctx.lineWidth = 4;
      ctx.strokeStyle = rgba("#ffffff", alpha * 0.9);
      for (i = 0; i < 3; i++) {
        r = rings[i];
        a = r.angle + mod(s - r.step, N) * SLOT;
        ctx.beginPath();
        ctx.arc(px(a, r.rad), py(a, r.rad), r.ballR * 1.16, 0, TAU);
        ctx.stroke();
      }
    }

    /* A ring blast: two FRONTS running around the plate from the charge's own
       housing, at exactly the speed of the fuses they are lighting, each
       trailing the glow of the arc it has already emptied. Drawing the whole
       span as one thick arc instead reads as a smear, not a wave — the eye
       needs the moving edge to believe it is travelling.
       Canvas measures its arcs from 3 o'clock; the dial measures from 12, hence
       the quarter turn. */
    function drawSweep(w) {
      // the front rides the FUSES, not the fade: it has to be over the bead
      // that is going off, or the picture and the board disagree
      var span = Math.min(1, w.t / w.travel) * Math.PI, fade = 1 - w.t / w.dur;
      var a0 = w.ring.angle + w.k * SLOT - Math.PI / 2, head = SLOT * 1.4;
      ctx.lineCap = "round";
      ctx.lineWidth = w.ring.band * 0.5;
      ctx.strokeStyle = rgba(w.hex, 0.24 * fade);
      ctx.beginPath(); ctx.arc(cx, cy, w.ring.rad, a0 - span, a0 + span); ctx.stroke();
      ctx.lineWidth = w.ring.band * 0.72;
      ctx.strokeStyle = rgba("#ffffff", 0.55 * fade);
      ctx.beginPath(); ctx.arc(cx, cy, w.ring.rad, a0 + span - head, a0 + span); ctx.stroke();
      ctx.beginPath(); ctx.arc(cx, cy, w.ring.rad, a0 - span, a0 - span + head); ctx.stroke();
      ctx.lineCap = "butt";
    }

    /* A bomb: the same shockwave as a nova's, wider and slower, and gold
       rather than the ray's own colour — it is the one wave that is not about
       a colour at all. */
    function drawBoom(w) {
      var p = w.t / w.dur, fade = 1 - p, rad = p * w.dur * D.bombSpeed;
      ctx.lineWidth = 26 * fade + 3;
      ctx.strokeStyle = rgba("#ffd43b", 0.30 * fade);
      ctx.beginPath(); ctx.arc(w.x, w.y, rad * 0.84, 0, TAU); ctx.stroke();
      ctx.lineWidth = 12 * fade + 2;
      ctx.strokeStyle = rgba("#ffffff", 0.60 * fade);
      ctx.beginPath(); ctx.arc(w.x, w.y, rad, 0, TAU); ctx.stroke();
    }

    /* A laser: the whole DIAMETER, drawn in one pass. It is the only effect on
       this dial that crosses the hub, which is exactly what makes it read as
       "through, and out the other side" rather than as one more flare. */
    function drawBeam(b) {
      var fade = 1 - b.t / b.dur, w = unit * 0.05 * (0.35 + fade);
      ctx.save();
      ctx.translate(cx, cy); ctx.rotate(b.s * SLOT);
      var g = ctx.createLinearGradient(0, -rimR, 0, rimR);
      g.addColorStop(0, rgba(b.hex, 0));
      g.addColorStop(0.14, rgba("#ffffff", 0.85 * fade));
      g.addColorStop(0.5, rgba("#ffffff", 0.95 * fade));
      g.addColorStop(0.86, rgba("#ffffff", 0.85 * fade));
      g.addColorStop(1, rgba(b.hex, 0));
      ctx.fillStyle = g;
      ctx.fillRect(-w / 2, -rimR, w, rimR * 2);
      ctx.restore();
    }

    /* A nova: one shockwave off the bead, travelling at the speed its fuses do. */
    function drawNova(w) {
      var p = w.t / w.dur, fade = 1 - p;
      var rad = p * w.dur * D.novaSpeed;
      ctx.lineWidth = 10 * fade + 2;
      ctx.strokeStyle = rgba("#ffffff", 0.45 * fade);
      ctx.beginPath(); ctx.arc(w.x, w.y, rad, 0, TAU); ctx.stroke();
      ctx.lineWidth = 22 * fade + 2;
      ctx.strokeStyle = rgba(w.hex, 0.24 * fade);
      ctx.beginPath(); ctx.arc(w.x, w.y, rad * 0.86, 0, TAU); ctx.stroke();
    }

    function drawFlare(f) {
      var e = f.life / D.flareTime, w = unit * 0.05 * (0.6 + e);
      ctx.save();
      ctx.translate(cx, cy); ctx.rotate(f.s * SLOT);
      var g = ctx.createLinearGradient(0, -hubR, 0, -rimR);
      g.addColorStop(0, rgba(f.hex, 0));
      g.addColorStop(0.5, rgba("#ffffff", 0.85 * e));
      g.addColorStop(1, rgba(f.hex, 0));
      ctx.fillStyle = g;
      ctx.fillRect(-w / 2, -rimR, w, rimR - hubR);
      ctx.restore();
    }

    /* The hub carries the two things the player has to keep an eye on and has
       nowhere else to put: the chain, and how close the next free CHARGE is.
       They are two concentric arcs on the cap, both starting at 12 o'clock. */
    function drawHub() {
      var i;
      ctx.fillStyle = rgba(D.hub, 0.96);
      ctx.beginPath(); ctx.arc(cx, cy, hubR, 0, TAU); ctx.fill();
      ctx.lineWidth = 3; ctx.strokeStyle = rgba(D.wire, 0.6);
      ctx.beginPath(); ctx.arc(cx, cy, hubR, 0, TAU); ctx.stroke();

      // outer arc: the charge meter, gold, one notch per ray
      var cp = clamp(charge / D.chargeNeed, 0, 1);
      ctx.lineWidth = 5;
      ctx.strokeStyle = rgba("#ffd43b", 0.16);
      ctx.beginPath(); ctx.arc(cx, cy, hubR - 7, 0, TAU); ctx.stroke();
      if (cp > 0) {
        ctx.strokeStyle = rgba("#ffd43b", 0.95);
        ctx.beginPath();
        ctx.arc(cx, cy, hubR - 7, -Math.PI / 2, -Math.PI / 2 + TAU * cp);
        ctx.stroke();
      }
      // the notches, so "one more ray" is countable rather than estimated
      ctx.lineWidth = 2; ctx.strokeStyle = rgba(D.hub, 1);
      for (i = 0; i < D.chargeNeed; i++) {
        var na = -Math.PI / 2 + TAU * (i / D.chargeNeed);
        ctx.beginPath();
        ctx.moveTo(cx + Math.cos(na) * (hubR - 10), cy + Math.sin(na) * (hubR - 10));
        ctx.lineTo(cx + Math.cos(na) * (hubR - 4), cy + Math.sin(na) * (hubR - 4));
        ctx.stroke();
      }

      if (combo >= 2) {
        // inner arc: the chain, and it IS its own countdown
        var p = clamp(comboLeft / D.comboWindow, 0, 1);
        ctx.lineWidth = 5;
        ctx.strokeStyle = rgba(combo >= 8 ? "#ffd43b" : "#35e0ff", 0.95);
        ctx.beginPath();
        ctx.arc(cx, cy, hubR - 17, -Math.PI / 2, -Math.PI / 2 + TAU * p);
        ctx.stroke();
        ctx.fillStyle = "#ffffff";
        ctx.font = "900 " + Math.round(hubR * 0.58) + "px -apple-system,BlinkMacSystemFont,sans-serif";
        ctx.textAlign = "center"; ctx.textBaseline = "middle";
        ctx.fillText("x" + combo, cx, cy + 1);
      } else {
        // the three plates, in miniature, on the cap they all turn on
        for (i = 0; i < 3; i++) {
          ctx.beginPath(); ctx.arc(cx, cy, hubR * (0.15 + 0.16 * i), 0, TAU);
          ctx.lineWidth = 3; ctx.strokeStyle = rgba(D.wire, 0.75); ctx.stroke();
        }
      }
    }

    /* A rounded rectangle path, written out because `ctx.roundRect` is still
       missing from the mobile WebViews this file has to run in. */
    function pill(x, y, w, h, r) {
      ctx.beginPath();
      ctx.moveTo(x + r, y);
      ctx.arcTo(x + w, y, x + w, y + h, r);
      ctx.arcTo(x + w, y + h, x, y + h, r);
      ctx.arcTo(x, y + h, x, y, r);
      ctx.arcTo(x, y, x + w, y, r);
      ctx.closePath();
    }

    /* THE SCORE WINDOW — the one piece of state on this dial that lives on a
       clock, so it is the one piece that needs somewhere to be read.

       Under the DISC, and that is not a free choice: the HUD's two slots are
       already the game's own (BEST and the clock in a CLASSIC round, LEVEL and
       RAYS in an eclipse one), and the band immediately under the HUD belongs
       to the level layer's three stars. The strip below the rim is the only
       part of the frame nothing else writes on — and it is under the dial the
       player is already looking at, which the top of the screen is not. It
       clamps into whatever room the frame leaves, so a squat ad iframe cannot
       push it off the bottom. */
    function drawMul() {
      if (mulLeft <= 0 || mulK <= 1) return;
      var w = Math.max(132, unit * 0.46), h = 34;
      var y = Math.min(cy + rimR + 30, Layout.bottom - h - 6);
      var x0 = cx - w / 2, p = clamp(mulLeft / mulSpan, 0, 1);
      ctx.fillStyle = rgba("#0a0720", 0.74);
      pill(x0, y, w, h, h / 2); ctx.fill();
      ctx.save();                                  // the window draining inside it
      pill(x0, y, w, h, h / 2); ctx.clip();
      ctx.fillStyle = rgba("#ffd43b", 0.26);
      ctx.fillRect(x0, y, w * p, h);
      ctx.restore();
      ctx.lineWidth = 2;
      ctx.strokeStyle = rgba("#ffd43b", 0.55 + 0.35 * p);
      pill(x0, y, w, h, h / 2); ctx.stroke();
      ctx.fillStyle = "#ffe98a";
      ctx.font = "900 " + Math.round(h * 0.58) + "px " +
                 "-apple-system,BlinkMacSystemFont,Segoe UI,sans-serif";
      ctx.textAlign = "center"; ctx.textBaseline = "middle";
      ctx.fillText(upper("x" + mulK + Lang.t("  score")), cx, y + h / 2 + 1);
    }

    function render() {
      var i, k, r, a, b, sc;
      ctx.drawImage(bg, 0, 0);

      for (i = 0; i < 3; i++) drawPlate(rings[i]);
      drawTeeth(rings[2]);

      // The rays the board is read on, drawn ON TOP of the plates and under
      // the beads: they are the one thing on screen that never moves, and a
      // player who cannot see them cannot see the game.
      ctx.save(); ctx.translate(cx, cy);
      ctx.lineWidth = 2; ctx.strokeStyle = rgba("#ffffff", 0.2);
      for (i = 0; i < N; i++) {
        // The rotate comes first, so this pass draws ray i+1.
        ctx.rotate(SLOT);
        if (Eclipse.on)
          ctx.strokeStyle = rgba("#ffffff", Eclipse.dead(mod(i + 1, N)) ? 0.05 : 0.2);
        ctx.beginPath(); ctx.moveTo(0, -hubR * 0.98); ctx.lineTo(0, -rimR); ctx.stroke();
      }
      ctx.restore();

      // The ink, over the machine and clipped to it, and under the beads:
      // a bead sitting on black is a ray that cannot pay. See Eclipse.
      if (Eclipse.on) Eclipse.draw(0);

      for (i = 0; i < 3; i++) {
        r = rings[i];
        for (k = 0; k < N; k++) {
          if (r.slots[k] === null) continue;
          a = r.angle + k * SLOT;
          drawBall(r.slots[k], i, px(a, r.rad), py(a, r.rad), 1, 1);
        }
      }

      for (i = 0; i < flyers.length; i++) {
        if (flyers[i].t < 0) continue;
        drawBall(flyers[i].colour, flyers[i].ring.idx, flyers[i].x, flyers[i].y, 1, flyers[i].a);
      }

      for (i = 0; i < blobs.length; i++) {
        b = blobs[i];
        sc = 1 + (1 - b.life / D.popTime) * 1.1;
        drawBall(b.v, b.idx, b.x, b.y, sc, b.life / D.popTime);
      }

      /* Light, over the beads rather than under them. Both of these have to
         read THROUGH a board that is already saturated, so they are drawn
         additively: a ray that would pay if the player let go now (breathing,
         with a halo on each of its three beads), and a ray that just did. */
      ctx.globalCompositeOperation = "lighter";
      if (armed && armed.length) {
        var glow = 0.34 + 0.16 * Math.sin(clock * 9);
        for (i = 0; i < armed.length; i++) drawArmed(armed[i], glow);
      }
      if (Eclipse.on) Eclipse.draw(1);
      for (i = 0; i < flares.length; i++) drawFlare(flares[i]);
      for (i = 0; i < sweeps.length; i++) drawSweep(sweeps[i]);
      for (i = 0; i < novas.length; i++) drawNova(novas[i]);
      for (i = 0; i < booms.length; i++) drawBoom(booms[i]);
      for (i = 0; i < beams.length; i++) drawBeam(beams[i]);
      ctx.globalCompositeOperation = "source-over";

      drawHub();
      drawMul();
      if (finale && finale.phase === "drama") drawFinale();
    }

    /* --- the finale --------------------------------------------------------
       The clock hitting zero is NOT the end of the round. Ending on that frame
       tears the plate out of the player's hand mid-turn and swallows whatever
       the move was about to pay — the one thing a 40-second game must not do.
       So time up opens a wind-down in two phases:

         settle  the move already under way finishes. The finger keeps the
                 plate it is holding, the dial pays what it lands on, and every
                 cascade, refill and super that follows plays out AND scores.
                 No new grab is taken (see onDown), so the phase is bounded by
                 the move the player had already started; `finaleWait` caps it
                 anyway, since a super chain can keep feeding itself.
         drama   the board is quiet at last — and has held still long enough
                 that the last dissolve, refill and spark are gone: the machine
                 powers down for `finaleDrama` seconds, and only then does the
                 end screen come.

       Everything the board still owes is therefore paid before the score is
       read, and the end screen arrives on a still dial the player is done with.
       ------------------------------------------------------------------- */

    /* Nothing of the round is moving any more: no finger on a plate, the three
       plates at rest, and no refill, fuse, wave, dissolve or lit ray left to
       play out. This is only the STRUCTURAL end of the move — the sparks a pop
       throws live in Fx, which the game cannot query, so the phase that uses
       this also holds `finaleCalm` seconds of it (see stepFinale). */
    function quiet() {
      return !grab && settled() && !flyers.length && !fuses.length &&
             !sweeps.length && !novas.length && !booms.length && !beams.length &&
             !blobs.length && !flares.length;
    }

    function onTimeUp() {
      finale = { phase: "settle", t: 0, calm: 0, struck: false };
      Music.duck(0.7, 0.5);          // the room quietens before the machine does
    }

    /* The power-down itself: the dial's own boom an octave under, the hazard
       callout, and the drain drawn in drawFinale. The second beat — the hub
       giving out — is fired from update once the light has finished draining,
       so the flash lands on the picture instead of ahead of it.

       The round gets exactly ONE danger callout: an eclipse already threw its
       own the moment the last ray went out, seconds before this, so only a
       CLASSIC round's clock announces itself here. */
    function powerDown() {
      Sound.clip("nova", 0.5, 0.55);
      Fx.shake(10, 0.5);
      if (!Eclipse.on) Pop.show("danger", { word: CONFIG.copy.timeUp });
    }

    function stepFinale(dt) {
      finale.t += dt;
      if (finale.phase === "settle") {
        /* The board has to be quiet AND stay quiet: a cascade goes through
           moments where nothing is left in the arrays but the beads are still
           dissolving and their sparks still in the air, and cutting to the
           power-down on one of those frames is the same jolt as ending on the
           clock. `finaleCalm` outlasts the longest of those (Fx.burst, 0.45 s),
           so the drama always opens on a board that has finished merging. */
        finale.calm = quiet() ? finale.calm + dt : 0;
        if (finale.calm < D.finaleCalm && finale.t < D.finaleWait) return;
        finale = { phase: "drama", t: 0, calm: 0, struck: false };
        powerDown();
        return;
      }
      if (!finale.struck && finale.t >= D.finaleDrain) {
        finale.struck = true;        // the hub takes the light and gives out
        Sound.clip("blast", 0.5, 0.7);
        Fx.flash("#ffffff", 0.3, 1.7);
        Fx.shake(16, 0.42);
      }
      if (finale.t >= D.finaleDrama) gameOver();
    }

    /* The dial losing power, drawn over everything so it reads as the machine
       going out rather than as one more effect happening on it: a ring of
       light collapsing from the rim into the hub, then the board dimming
       under the callout for what is left of the two seconds. */
    function drawFinale() {
      var d = clamp(finale.t / D.finaleDrain, 0, 1), rad, veil;
      if (d < 1) {
        rad = rimR + (hubR - rimR) * (d * d * (3 - 2 * d));
        ctx.globalCompositeOperation = "lighter";
        ctx.lineWidth = 10 + 30 * (1 - d);
        ctx.strokeStyle = rgba(D.colours[3], 0.10 + 0.30 * d);
        ctx.beginPath(); ctx.arc(cx, cy, rad, 0, TAU); ctx.stroke();
        ctx.lineWidth = 5;
        ctx.strokeStyle = rgba("#ffffff", 0.25 + 0.55 * d);
        ctx.beginPath(); ctx.arc(cx, cy, rad, 0, TAU); ctx.stroke();
        ctx.globalCompositeOperation = "source-over";
      }
      veil = clamp((finale.t - D.finaleDrain) / 0.45, 0, 1) * 0.5;
      if (veil > 0) {
        ctx.fillStyle = rgba("#05040f", veil);
        ctx.fillRect(0, 0, view.w, view.h);
      }
    }

    function gameOver() {
      var stars = score >= D.star3 ? 3 : score >= D.star2 ? 2 : score > 0 ? 1 : 0;
      /* Four rows, and four in both modes: the fifth is what the end screen
         spends on its character (docs/ENGINE.md, `CONFIG.art`). The two
         leading rows are the ones the mode disagrees about — the dial counts
         what was popped, eclipse counts how long it was held off — and the
         chain and the best score close either of them. */
      var rows = Eclipse.on ? [
        { label: "Level", value: Eclipse.level(), grade: "gold" },
        { label: "Survived", value: Eclipse.survived() + "s", grade: "accent" }
      ] : [
        { label: "Rays popped", value: matches },
        { label: "Biggest blast", value: bestBlast + Lang.t(" beads"),
          grade: bestBlast >= 8 ? "good" : "" }
      ];
      rows.push(
        { label: "Best chain", value: "x" + bestCombo, grade: "accent" },
        { label: "Best score", value: Math.max(score, best), grade: "gold" });
      endRound({
        title: Eclipse.on ? CONFIG.copy.eclipsed
                         : stars === 3 ? Lang.t("Radiant!") : CONFIG.copy.timeUp,
        variant: stars === 3 ? "perfect" : stars === 2 ? "win" : "",
        score: score,
        stars: stars,
        rows: rows
      });
    }

    /* --- THE LEVEL LAYER (web target) ------------------------------------
       `applyLevel(d)` is the escape hatch a lerp cannot cover (docs/LEVELS.md):
       the level layer lerps the manifest's four `dial.*` knobs first and then
       hands the game its own difficulty, 0 at the foot of the climb and 1 at
       the top. Everything that makes a level a DIFFERENT game rather than a
       harder one comes through here — the biome, the specials in play, how
       much ice the refills carry, and how big a face the SCORE bead may wear.

       It is called BEFORE reset(), which is what lets it write the biome and
       the style straight into place: reset -> layout -> buildSprites bakes the
       new bead out of the new style's cuts, and buildBg repaints the hall under
       it, without a call of its own.

       `null` is the playable and the endless run at 90/90, and it puts the
       machine back exactly the way the file wrote it. Every read of BIO has a
       fallback for the same reason. */
    function applyLevel(d) {
      var n = CONFIG.level | 0, i, row;
      if (!n || d == null) {
        BIO = null; POOL = ["charge", "nova"]; ICE_RATE = 0; MUL_FACE = 1;
        /* A WEB build with no level is the endless run a perfect board
           unlocks, and it gets the style held back for it; a PLAYABLE has no
           levels at all and carries only the base one, because the builder
           holds the other fourteen back from a creative that could never show
           them. `CONFIG.slug` is what tells the two apart — the web build
           injects it and a creative never has it. */
        STYLE = CONFIG.slug ? LAD.bonusStyle : LAD.baseStyle;
        D.sky = SKIN0.sky.slice();
        D.wire = SKIN0.wire; D.plate = SKIN0.plate; D.hub = SKIN0.hub;
        return;
      }

      // The biome is the stretch of the climb the LEVEL NUMBER sits in, never
      // the difficulty: the two roads out of a fork have to be the same world.
      BIO = LAD.biomes[0];
      for (i = 0; i < LAD.biomeFrom.length; i++) if (n >= LAD.biomeFrom[i]) BIO = LAD.biomes[i];
      D.sky = BIO.sky.slice();
      D.wire = BIO.wire; D.plate = BIO.plate; D.hub = BIO.hub;

      /* ...and the bead, which turns over twice as fast as the room: one style
         per PAIR of levels, so thirty levels are fifteen boards. Clamped rather
         than wrapped — a thirty-first level would otherwise start the set again
         and read as a mistake, where holding the last one reads as the top. */
      STYLE = LAD.styles[Math.min(LAD.styles.length - 1, Math.floor((n - 1) / 2))];

      row = LAD.levels[(n - 1) % LAD.levels.length];
      POOL = row.pool.slice();
      ICE_RATE = row.ice || 0;

      /* The SCORE bead's face climbs with the round, not with the dice: x2 at
         the foot, x5 from the middle, x10 only where the level is long enough
         that a four-second window is worth planning a move around. */
      MUL_FACE = d < 0.34 ? 1 : d < 0.68 ? 2 : 3;
    }

    /* The three-star finish: the web shell has already played the slow motion,
       and the round ends through the game's own result so the end screen keeps
       its stat rows. Ignored by the playable, which has no levels. */
    return { reset: reset, update: update, render: render,
             onDown: onDown, onMove: onMove, onUp: onUp,
             onTimeUp: onTimeUp, onResize: onResize,
             applyLevel: applyLevel, levelWon: gameOver };
  })();

